        var installed = new List<IDictionary<string, IReadOnlyList<KismetStep>>>();
        foreach (string name in new[] { "card_unit_typhoon_mk_ib", "card_event_honorifics", "card_unit_51e_regiment" })
        {
            if (KismetLibrary.Default?.Find(name)?.Locals is not IDictionary<string, IReadOnlyList<KismetStep>> locals
                || KismetLibrary.Default.FindProgram(name, trigger) is not null)
            {
                foreach (var item in installed) item.Remove(trigger);
                return "无法安全安装前线归属探针";
            }
            locals.Add(trigger, new[] {
                new KismetStep(0, "set", null, Array.Empty<KismetExpr>(), Array.Empty<int>(),
                    new KismetExpr { Var = "instigator", Scope = "local" }, null, -1, "_auditFrontlineSource", null) { DestinationScope = "instance" },
                new KismetStep(1, "set", null, Array.Empty<KismetExpr>(), Array.Empty<int>(),
                    new KismetExpr { Var = "oldSide", Scope = "local" }, null, -1, "_auditFrontlineOld", null) { DestinationScope = "instance" },
                new KismetStep(2, "set", null, Array.Empty<KismetExpr>(), Array.Empty<int>(),
                    new KismetExpr { Var = "newSide", Scope = "local" }, null, -1, "_auditFrontlineNew", null) { DestinationScope = "instance" },
                new KismetStep(3, "call", "SpawnCardInDeckBySide", new[] {
                    new KismetExpr { Int = (int)Side.Right }, new KismetExpr { Str = "card_unit_routed_troops" },
                    new KismetExpr { Int = 30 }, new KismetExpr { Int = 1 }
                }, Array.Empty<int>(), null, null, -1, null, null),
                new KismetStep(4, "return", null, Array.Empty<KismetExpr>(), Array.Empty<int>(), null, null, -1, null, null) });
            installed.Add(locals);
        }
        try
        {
            foreach (Side side in new[] { Side.Left, Side.Right })
            foreach (int mode in Enumerable.Range(0, 11))
            {
                var (engine, state) = EmptyBoard(db);
                var subject = state.CreateWithId("card_unit_typhoon_mk_ib", side, 60,
                    mode >= 9 ? side.HandOf() : CardLocation.BoardFrontline, 0);
                var first = state.CreateWithId("card_event_honorifics", side, 20, side.HqOf(), 1);
                var last = state.CreateWithId("card_unit_51e_regiment", side, 21,
                    mode == 2 ? CardLocation.NotAvailable : side.HqOf(), 2);
                var cards = new[] { first, last, subject };
                foreach (var card in cards) card.Definition = new CardDefinition { Name = card.Name, UsedTriggers = new[] { trigger } };
                Side old = mode == 9 ? side : mode == 10 ? Side.NotAvailable : mode == 8 ? side : side.Opposite();
                state.FrontlineOwner = old;
                if (mode == 1) state.StopFurtherActions = true;
                if (mode is 4 or 5) first.Keywords.Add(Keyword.Suppressed);
                if (mode == 5) first.SuppressionExceptionTriggers.Add(trigger);
                var called = new List<int>(); var created = state.CardCreated;
                state.CardCreated = made => {
                    created?.Invoke(made);
                    if (made.Name != "card_unit_routed_troops") return;
                    var current = cards.Single(x => !called.Contains(x.CardId)
                        && x.BlueprintVariables.ContainsKey("_auditFrontlineNew"));
                    called.Add(current.CardId);
                    if (current == first)
                    {
                        if (mode == 3) { last.Keywords.Add(Keyword.Suppressed); last.Location = CardLocation.NotAvailable; }
                        if (mode == 6) { state.FrontlineOwner = side.Opposite(); state.StopFurtherActions = true; }
                        if (mode == 7) state.FrontlineOwner = Side.NotAvailable;
                    }
                };
                state.CardMoved?.Invoke(subject, side.HqOf(), CardLocation.BoardFrontline, false, CardMoveReason.PlayCardForce);
                int[] expected = mode is 8 or 10 ? Array.Empty<int>() : mode == 4 ? new[] { 21, 60 } : new[] { 20, 21, 60 };
                if (!called.SequenceEqual(expected))
                    return $"T27快照资格错误：{side} mode={mode} 实际{string.Join(",", called)}";
                foreach (int id in called)
                {
                    var card = cards.Single(x => x.CardId == id);
                    Side expectedNew = mode == 9 || mode == 7 && id != 20 ? Side.NotAvailable
                        : mode == 6 && id != 20 ? side.Opposite() : side;
                    if (Convert.ToInt32(card.BlueprintVariables["_auditFrontlineSource"]) != 60
                        || Convert.ToInt32(card.BlueprintVariables["_auditFrontlineOld"]) != (int)old
                        || Convert.ToInt32(card.BlueprintVariables["_auditFrontlineNew"]) != (int)expectedNew)
                        return $"T27应固定oldSide但逐项读取newSide：{side} mode={mode} 接收者{id}";
                }
            }
            return null;
        }
        finally { foreach (var item in installed) item.Remove(trigger); }
    }

    // Temporary registered definitions and programs probe the dispatcher only;
    // these are not assertions about the named live cards' actual abilities.
    private static IDisposable InstallMovementObserverProbes()
    {
        var installed = new List<(IDictionary<string, IReadOnlyList<KismetStep>> Locals, string Trigger)>();
        foreach (string name in new[] { "card_unit_typhoon_mk_ib", "card_event_honorifics", "card_unit_51e_regiment" })
        foreach (string trigger in new[] { "OnCardLocationMoved", "OnOtherCardLocationMoved", "OnMoveFromFrontline", "OnOtherCardMoveFromFrontline" })
        {
            if (KismetLibrary.Default?.Find(name)?.Locals is not IDictionary<string, IReadOnlyList<KismetStep>> locals
                || KismetLibrary.Default.FindProgram(name, trigger) is not null)
            {
                foreach (var item in installed) item.Locals.Remove(item.Trigger);
                throw new InvalidOperationException("无法安全安装移动事件探针：" + name + " " + trigger);
            }
            locals.Add(trigger, new[] {
                new KismetStep(0, "set", null, Array.Empty<KismetExpr>(), Array.Empty<int>(),
                    new KismetExpr { Bool = true }, null, -1, "_auditMovementCalled", null) { DestinationScope = "instance" },
                new KismetStep(1, "call", "SpawnCardInDeckBySide", new[] {
                    new KismetExpr { Int = (int)Side.Right }, new KismetExpr { Str = "card_unit_routed_troops" },
                    new KismetExpr { Int = 30 }, new KismetExpr { Int = 1 }
                }, Array.Empty<int>(), null, null, -1, null, null),
                new KismetStep(2, "return", null, Array.Empty<KismetExpr>(), Array.Empty<int>(), null, null, -1, null, null) });
            installed.Add((locals, trigger));
        }
        return new AuditProbeCleanup(() => { foreach (var item in installed) item.Locals.Remove(item.Trigger); });
    }

    private static string? MovementObserverSnapshots(CardDatabase db)
    {
        using var probes = InstallMovementObserverProbes();
        foreach (bool retreat in new[] { false, true })
        foreach (Side side in new[] { Side.Left, Side.Right })
        foreach (int mode in Enumerable.Range(0, 11))
        {
            var (engine, state) = EmptyBoard(db);
            string trigger = retreat ? "OnOtherCardMoveFromFrontline" : "OnOtherCardLocationMoved";
            var subject = state.CreateWithId("card_unit_typhoon_mk_ib", side, 60, side.HqOf(), 1);
            var first = state.CreateWithId("card_event_honorifics", side, 20, side.HqOf(), 2);
            var last = state.CreateWithId("card_unit_51e_regiment", side, 21, mode == 9 ? CardLocation.NotAvailable : side.HqOf(), 3);
            var cards = new[] { subject, first, last };
            foreach (var card in cards) card.Definition = new CardDefinition { Name = card.Name, UsedTriggers = new[] { trigger } };
            if (mode == 1) state.StopFurtherActions = true;
            if (mode == 5) subject.Keywords.Add(Keyword.Suppressed);
            if (mode is 6 or 7) first.Keywords.Add(Keyword.Suppressed);
            if (mode == 6) first.SuppressionExceptionTriggers.Add(trigger);
            var called = new List<int>(); var created = state.CardCreated;
            state.CardCreated = made => {
                created?.Invoke(made);
                if (made.Name != "card_unit_routed_troops") return;
                var current = cards.Single(x => !called.Contains(x.CardId)
                    && Equals(x.BlueprintVariables.GetValueOrDefault("_auditMovementCalled"), true));
                called.Add(current.CardId);
                if (current == subject)
                {
                    if (mode == 2) state.StopFurtherActions = true;
                    if (mode == 4) first.Keywords.Add(Keyword.Suppressed);
                    if (mode == 10) subject.Location = CardLocation.NotAvailable;
                }
                if (current == first)
                {
                    if (mode == 3) state.StopFurtherActions = true;
                    if (mode == 8) { last.Keywords.Add(Keyword.Suppressed); last.Location = CardLocation.NotAvailable; }
                }
            };
            if (retreat) engine.ExecuteOnCardMoveFromFrontline(subject);
            else engine.ExecuteOnCardLocationMoved(subject, CardLocation.BoardFrontline, side.HqOf(), true, CardMoveReason.ControlRelease);
            var expected = mode == 5 ? new List<int>() : new List<int> { 60 };
            if (!(retreat && mode is 1 or 2))
            {
                if (mode is not (4 or 7)) expected.Add(20);
                if (!(retreat && mode == 3)) expected.Add(21);
            }
            if (!called.SequenceEqual(expected))
                return $"移动快照错误：T{(retreat ? 49 : 47)} {side} mode={mode} 期望{string.Join(",", expected)} 实际{string.Join(",", called)}";
        }
        return null;
    }

    private static string? MovementUnavailableOwnHook(CardDatabase db)
    {
        using var probes = InstallMovementObserverProbes();
        foreach (bool retreat in new[] { false, true })
        foreach (Side side in new[] { Side.Left, Side.Right })
        {
            var (engine, state) = EmptyBoard(db);
            var subject = state.CreateWithId("card_unit_typhoon_mk_ib", side, 60, CardLocation.NotAvailable, 0);
            if (retreat) engine.ExecuteOnCardMoveFromFrontline(subject);
            else engine.ExecuteOnCardLocationMoved(subject, CardLocation.BoardFrontline, CardLocation.NotAvailable);
            if (!Equals(subject.BlueprintVariables.GetValueOrDefault("_auditMovementCalled"), true))
                return "原生移动自身回调没有额外NotAvailable门";
        }
        return null;
    }

    private static string? BettyDiscardDirectEntry(CardDatabase db)
    {
        foreach (Side side in new[] { Side.Left, Side.Right })
        foreach (bool full in new[] { false, true })
        {
            var (engine, state) = EmptyBoard(db);
            if (full) for (int i = 1; i < GameState.HalfBoardCapacity; i++)
                state.CreateWithId("card_unit_432_infantry_regiment", side, 100 + i, side.HqOf(), i);
            var card = state.CreateWithId("card_unit_g4m1_betty", side, 60, side.HandOf(), 0);
            var other = state.CreateWithId("card_unit_432_infantry_regiment", side, 61, side.HandOf(), 1);
            var context = new EffectContext { Engine = engine, State = state, Self = card, Controller = side };
            var result = engine.Api.InvokeByName("DiscardCardFromHand", card,
                new object?[] { 60, 9004, false, false, null }, context, out _);
            if (result is not false || card.Location != (full ? CardLocation.Discard : side.HqOf())
                || other.Location != side.HandOf() || state.CardsPlayedThisTurn.Count != 0
                || state.ActionLog.SelectMany(x => x.SubActions).Count(x => x.Name == "ZActionDiscardCard") != (full ? 1 : 0))
                return $"G4M1尝试弃牌重入错误：{side} 满员{full}";
        }
        return null;
    }

    private static string? DirectNonGotchaEntryBoundary(CardDatabase db)
    {
        foreach (Side side in new[] { Side.Left, Side.Right })
        foreach (bool frontline in new[] { false, true })
        foreach (bool suppressed in new[] { false, true })
        foreach (bool salvaged in new[] { false, true })
        foreach (string name in new[] { "card_unit_10_5_cm_lefh", "card_event_calm_before_the_storm", "card_event_sunny1_blue_sky" })
        {
            var (engine, state) = EmptyBoard(db);
            state.ActiveSide = side.Opposite(); state.Turn = 7;
            state.SetKredits(side, 4); state.StopFurtherActions = true;
            var card = state.CreateWithId(name, side, 60, side.HandOf(), 7);
            var remaining = state.CreateWithId("card_unit_432_infantry_regiment", side, 61, side.HandOf(), 15);
            var target = state.Hq(side.Opposite()); int defense = target.Defense;
            card.BlueprintVariables["targetOverride"] = target;
            card.CurrentTarget = remaining; card.IsSalvaged = salvaged;
            card.CardSeen = true; card.KreditCost = 1;
            if (suppressed) card.Keywords.Add(Keyword.Suppressed);
            var trace = new List<string>(); engine.Api.TriggerTrace = trace;
            bool result = engine.PlayCardDirectlyFromHand(card, frontline, 9004, -1);
            var actions = state.ActionLog.SelectMany(x => x.SubActions).ToArray();
            var play = actions.SingleOrDefault(x => x.Name == "ZActionPlayCardFromHand");
            var move = actions.SingleOrDefault(x => x.Name == "ZActionMoveCardToNewLocation");
            int slot = frontline ? 0 : 1;
            if (!result || card.Location != (frontline ? CardLocation.BoardFrontline : side.HqOf())
                || card.LocationNumber != slot || remaining.LocationNumber != 0
                || card.EnteredPlayOnTurn != 7 || card.CardSeen || card.CurrentTarget != remaining
                || card.KreditCost != (salvaged ? Math.Min(3, card.Definition.Kredits) : card.Definition.Kredits)
                || state.Kredits(side) != 4 || state.Turn != 7 || target.Defense != defense
                || state.CardsPlayedThisTurn.Count != 0 || state.HasPlayedWeatherCardThisTurn || !state.StopFurtherActions
                || trace.Any(x => x.StartsWith("OnPlayedFromHand", StringComparison.Ordinal)
                    || x.StartsWith("OnOtherCardPlayedFromHand", StringComparison.Ordinal)
                    || x.StartsWith("OnBeforeOtherCardPlayedFromHand", StringComparison.Ordinal))
                || play is null || move is null || Array.IndexOf(actions, play) >= Array.IndexOf(actions, move)
                || play.Values.First(x => x.Name == "targetCardID").Value != target.CardId
                || play.Values.First(x => x.Name == "instigatorID").Value != 9004
                || play.Values.First(x => x.Name == "locationNumber").Value != slot
                || !play.Values.Any(x => x.Name == "playedDirectly" && x.Value == 1)
                || move.Values.First(x => x.Name == "newLocationNumber").Value != slot)
                return $"直接出牌边界错误：{side} 前线{frontline} 抑制{suppressed} 打捞{salvaged} {name}";
        }
        return null;
    }

    private static string? DirectEntryFieldOrder(CardDatabase db)
    {
        const string name = "card_unit_typhoon_mk_ib", trigger = "OnEnterPlay";
        if (KismetLibrary.Default?.Find(name)?.Locals is not IDictionary<string, IReadOnlyList<KismetStep>> locals
            || KismetLibrary.Default.FindProgram(name, trigger) is not null) return "无法安全安装直接入场探针";
        // Synthetic own-entry reentry marker, not a claim about Typhoon's real effects.
        locals.Add(trigger, new[] {
            new KismetStep(0, "set", null, Array.Empty<KismetExpr>(), Array.Empty<int>(),
                new KismetExpr { Var = "Method", Scope = "local" }, null, -1, "_auditEntryMethod", null) { DestinationScope = "instance" },
            new KismetStep(1, "call", "SpawnCardInDeckBySide", new[] {
                new KismetExpr { Int = (int)Side.Right }, new KismetExpr { Str = "card_unit_routed_troops" },
                new KismetExpr { Int = 30 }, new KismetExpr { Int = 1 }
            }, Array.Empty<int>(), null, null, -1, null, null),
            new KismetStep(2, "return", null, Array.Empty<KismetExpr>(), Array.Empty<int>(), null, null, -1, null, null) });
        try
        {
            foreach (Side side in new[] { Side.Left, Side.Right })
            foreach (bool frontline in new[] { false, true })
            foreach (bool timer in new[] { false, true })
            {
                var (engine, state) = EmptyBoard(db); state.Turn = 7;
                var card = state.CreateWithId(name, side, 60, side.HandOf(), 7);
                var first = state.CreateWithId("card_unit_panzer_iii_e", side, 20, side.HqOf(), 1);
                state.CreateWithId(first.Name, side, 21, CardLocation.NotAvailable, 0);
                var alpine = state.CreateWithId("card_unit_432_infantry_regiment", side, 22, side.HqOf(), 2);
                alpine.Keywords.Add(Keyword.Alpine); card.Keywords.Add(Keyword.Alpine);
                card.KreditCost = 1; card.CardSeen = true; card.IsSalvaged = timer;
                engine.Api.JsonSetInt(card, "unrelated", 19);
                if (timer) engine.Api.JsonSetInt(card, "countdown_timer", 3);
                int atEntryAttack = -1, atEntryCost = -1, atEntryTurn = -1;
                bool atEntrySeen = true, atEntryTimer = true;
                int beforeAttack = card.Attack;
                var created = state.CardCreated;
                state.CardCreated = made => {
                    created?.Invoke(made);
                    if (made.Name != "card_unit_routed_troops") return;
                    atEntryAttack = card.Attack; atEntryCost = card.KreditCost;
                    atEntryTurn = card.EnteredPlayOnTurn; atEntrySeen = card.CardSeen;
                    atEntryTimer = card.CustomJson.ContainsKey("countdown_timer");
                    first.Keywords.Add(Keyword.Suppressed);
                };
                var trace = new List<string>(); engine.Api.TriggerTrace = trace;
                if (!engine.PlayCardDirectlyFromHand(card, frontline, 9004, 1)
                    || Convert.ToInt32(card.BlueprintVariables.GetValueOrDefault("_auditEntryMethod")) != 2
                    || atEntryAttack != beforeAttack || card.Attack != beforeAttack + 1
                    || atEntryCost != (timer ? Math.Min(3, card.Definition.Kredits) : card.Definition.Kredits)
                    || atEntryTurn != 7 || atEntrySeen || atEntryTimer || engine.Api.JsonGetInt(card, "unrelated") != 19
                    || trace.Any(x => x.StartsWith("OnOtherCardEnterPlay → card_unit_panzer_iii_e#20", StringComparison.Ordinal))
                    || !trace.Any(x => x.StartsWith("OnOtherCardEnterPlay → card_unit_panzer_iii_e#21", StringComparison.Ordinal)))
                    return $"直接入场顺序错误：{side} 前线{frontline} 计时{timer} Method={card.BlueprintVariables.GetValueOrDefault("_auditEntryMethod")} 攻{atEntryAttack}->{card.Attack} 费{atEntryCost}";
                int persist = state.ActionLog.SelectMany(x => x.SubActions).Count(x => x.Name == "ZActionPersistCustomFields"
                    && x.Values.Any(v => v.Name == "cardID" && v.Value == 60));
                if (persist != (timer ? 1 : 0)) return "仅删除了countdown_timer时应持久化该卡JSON";
            }
            foreach (Side side in new[] { Side.Left, Side.Right })
            {
                var (engine, state) = EmptyBoard(db);
                var card = state.CreateWithId(name, side, 60, CardLocation.NotAvailable, 0);
                engine.ExecuteOnEnterPlayEvents(card, 5);
                if (Convert.ToInt32(card.BlueprintVariables.GetValueOrDefault("_auditEntryMethod")) != 5)
                    return "原生入场自身回调没有NotAvailable位置门";
            }
            return null;
        }
        finally { locals.Remove(trigger); }
    }

    private static string? DirectEntryHandEdges(CardDatabase db)
    {
        foreach (Side side in new[] { Side.Left, Side.Right })
        foreach (int index in new[] { 0, 1, 2 })
        {
            var (engine, state) = EmptyBoard(db);
            var hand = Enumerable.Range(0, 3).Select(i => state.CreateWithId("card_unit_432_infantry_regiment", side, 60 + i, side.HandOf(), i)).ToArray();
            var card = hand[index];
            engine.Api.JsonSetBool(card, "WasLeftMostCardWhenPlayedFromHand", true);
            engine.Api.JsonSetBool(card, "WasRightMostWhenPlayedFromHandKey", true);
            engine.PlayCardDirectlyFromHand(card, false, 9004, -1);
            if (engine.Api.JsonGetBool(card, "WasLeftMostCardWhenPlayedFromHand") != (index == 0)
                || engine.Api.JsonGetBool(card, "WasRightMostWhenPlayedFromHandKey") != (index == 2)
                || state.Hand(side).Select(x => x.LocationNumber).Order().SequenceEqual(new[] { 0, 1 }) != true)
                return $"直接入场手牌两端标记错误：{side} index={index}";
        }
        return null;
    }

    private static string? HandDiscardSuccessReentry(CardDatabase db)
    {
        const string name = "card_unit_typhoon_mk_ib", trigger = "OnSuccesfulDiscard";
        if (KismetLibrary.Default?.Find(name)?.Locals is not IDictionary<string, IReadOnlyList<KismetStep>> locals
            || locals.ContainsKey(trigger)) return "无法安全添加成功弃牌探针";
        locals.Add(trigger, new[] {
            new KismetStep(0, "call", "SpawnCardInDeckBySide", new[] {
                new KismetExpr { Int = (int)Side.Right }, new KismetExpr { Str = "card_unit_routed_troops" },
                new KismetExpr { Int = 30 }, new KismetExpr { Int = 1 }
            }, Array.Empty<int>(), null, null, -1, null, null),
            new KismetStep(1, "call", "SuppressUnit", new[] { new KismetExpr { Int = 20 } }, Array.Empty<int>(), null, null, -1, null, null),
            new KismetStep(2, "return", null, Array.Empty<KismetExpr>(), Array.Empty<int>(), null, null, -1, null, null) });
        try
        {
            foreach (Side side in new[] { Side.Left, Side.Right })
            foreach (bool random in new[] { false, true })
            {
                var (engine, state) = EmptyBoard(db);
                var card = state.CreateWithId(name, side, 60, side.HandOf(), 7);
                state.CreateWithId("card_unit_211th_basargino", side, 20, side.HqOf(), 1);
                var created = state.CardCreated;
                state.CardCreated = made => {
                    created?.Invoke(made);
                    if (made.Name == "card_unit_routed_troops") card.Location = CardLocation.NotAvailable;
                };
                var trace = new List<string>(); engine.Api.TriggerTrace = trace;
                var context = new EffectContext { Engine = engine, State = state, Self = card, Controller = side };
                var result = engine.Api.InvokeByName(random ? "DiscardRandomCardFromHand" : "DiscardCardFromHand", card,
                    random ? new object?[] { (int)side, 9004, null } : new object?[] { 60, 9004, false, false, null }, context, out _);
                if (!(random ? result is 60 : result is true) || card.Location != CardLocation.NotAvailable
                    || trace.Any(x => x.StartsWith("OnOtherCardDiscarded → card_unit_211th_basargino#20", StringComparison.Ordinal)))
                    return "成功回调改位置不应改变返回值；回调抑制的观察者应在后续T41查询被过滤";
            }
            return null;
        }
        finally { locals.Remove(trigger); }
    }

    private static string? HandDiscardCancellationFlags(CardDatabase db)
    {
        // Same program as DeckDiscardCancellation: the local-program cache may
        // retain it, so use exactly the same probe body for this shared name.
        const string name = "card_unit_typhoon_mk_ib", trigger = "OnAttemptedDiscard";
        if (KismetLibrary.Default?.Find(name)?.Locals is not IDictionary<string, IReadOnlyList<KismetStep>> locals
            || locals.ContainsKey(trigger)) return "无法安全添加手牌取消探针";
        locals.Add(trigger, new[] {
            new KismetStep(0, "set", null, Array.Empty<KismetExpr>(), Array.Empty<int>(),
                new KismetExpr { Var = "discarderID", Scope = "local" }, null, -1, "_auditDiscarder", null) { DestinationScope = "instance" },
            new KismetStep(1, "set", null, Array.Empty<KismetExpr>(), Array.Empty<int>(),
                new KismetExpr { Bool = true }, null, -1, "cancelDiscard", null) { DestinationScope = "local" },
            new KismetStep(2, "return", null, Array.Empty<KismetExpr>(), Array.Empty<int>(), null, null, -1, null, null) });
        try
        {
            foreach (Side side in new[] { Side.Left, Side.Right })
            foreach (int source in new[] { 0, 9004 })
            foreach (bool force in new[] { false, true })
            foreach (bool restricted in new[] { false, true })
            foreach (bool suppressed in new[] { false, true })
            {
                var (engine, state) = EmptyBoard(db);
                var card = state.CreateWithId(name, side, 60, side.HandOf(), 7);
                if (restricted) state.AddGameplayRestriction(side, GameplayRestrictionType.CannotDiscardAnyCardFromHand, 30, 2);
                if (suppressed) card.Keywords.Add(Keyword.Suppressed);
                var context = new EffectContext { Engine = engine, State = state, Self = card, Controller = side };
                object? result = engine.Api.InvokeByName("DiscardCardFromHand", card,
                    new object?[] { 60, source, false, force, null }, context, out _);
                bool expected = force || suppressed && !restricted;
                bool attempted = !force && !restricted && !suppressed;
                if (!Equals(result, expected) || (card.Location == CardLocation.Discard) != expected
                    || card.BlueprintVariables.ContainsKey("_auditDiscarder") != attempted
                    || attempted && Convert.ToInt32(card.BlueprintVariables["_auditDiscarder"]) != source)
                    return $"手牌取消门错误：{side} 来源{source} 强制{force} 限制{restricted} 抑制{suppressed}";
                var actions = state.ActionLog.SelectMany(x => x.SubActions).Where(x => x.Name == "ZActionDiscardCard").ToArray();
                if (actions.Length != (expected ? 1 : 0)
                    || expected && actions[0].Values.First(x => x.Name == "discarderID").Value != source)
                    return "手牌弃牌必须保留原始来源，包括不存在的正ID";
                if (!expected)
                {
                    object? selected = engine.Api.InvokeByName("DiscardRandomCardFromHand", card,
                        new object?[] { (int)side, source, null }, context, out _);
                    if (selected is not 60 || card.Location != side.HandOf())
                        return "随机弃牌取消后仍应返回选中的卡ID";
                }
            }
            return null;
        }
        finally { locals.Remove(trigger); }
    }

    private static string? HandDiscardNotificationBoundary(CardDatabase db)
    {
        foreach (Side side in new[] { Side.Left, Side.Right })
        foreach (bool skip in new[] { false, true })
        foreach (bool suppressed in new[] { false, true })
        {
            var (engine, state) = EmptyBoard(db);
            var card = state.CreateWithId("card_unit_sally", side, 60, side.HandOf(), 7);
            var remaining = state.CreateWithId("card_unit_432_infantry_regiment", side, 61, side.HandOf(), 15);
            var oldDiscard = state.CreateWithId(remaining.Name, side, 62, CardLocation.Discard, 17);
            state.CreateWithId(remaining.Name, side, 63, side.DeckOf(), 0);
            state.CreateWithId(remaining.Name, side, 64, side.DeckOf(), 1);
            var observer = state.CreateWithId("card_unit_211th_basargino", side, 20, CardLocation.NotAvailable, 0);
            if (suppressed) card.Keywords.Add(Keyword.Suppressed);
            var trace = new List<string>(); engine.Api.TriggerTrace = trace;
            int moves = 0;
            var previous = state.CardMoved;
            state.CardMoved = (c, oldLocation, newLocation, ownerChange, reason) => {
                if (c == card) moves++;
                previous?.Invoke(c, oldLocation, newLocation, ownerChange, reason);
            };
            var context = new EffectContext { Engine = engine, State = state, Self = card, Controller = side };
            var result = engine.Api.InvokeByName("DiscardCardFromHand", card,
                new object?[] { 60, 9004, skip, false, null }, context, out _);
            var actions = state.ActionLog.SelectMany(x => x.SubActions).Where(x => x.Name == "ZActionDiscardCard").ToArray();
            if (result is not true || card.LocationNumber != 7 || oldDiscard.LocationNumber != 17
                || remaining.LocationNumber != 0 || moves != 0 || actions.Length != (skip ? 0 : 1)
                || state.Hand(side).Count != (suppressed ? 1 : 3)
                || !trace.Any(x => x.StartsWith("OnOtherCardDiscarded → card_unit_211th_basargino#20", StringComparison.Ordinal)))
                return $"手牌弃牌通知边界错误：{side} skip={skip} 抑制={suppressed}";
            if (!skip && (actions[0].Values.First(x => x.Name == "cardID").Value != 60
                || actions[0].Values.First(x => x.Name == "discarderID").Value != 9004
                || actions[0].Values.First(x => x.Name == "oldLocation").Text != (side == Side.Left ? "Hand_Left" : "Hand_Right")))
                return "手牌弃牌通知缺失原始卡/来源/旧位置";
        }
        foreach (Side side in new[] { Side.Left, Side.Right })
        {
            var (engine, state) = EmptyBoard(db);
            var wrongOwner = state.CreateWithId("card_unit_432_infantry_regiment", side.Opposite(), 59, side.HandOf(), 0);
            var card = state.CreateWithId(wrongOwner.Name, side, 60, side.HandOf(), 1);
            var context = new EffectContext { Engine = engine, State = state, Self = card, Controller = side };
            var result = engine.Api.InvokeByName("DiscardRandomCardFromHand", card,
                new object?[] { (int)side, 9004, null }, context, out _);
            if (result is not 60 || wrongOwner.Location != side.HandOf() || card.Location != CardLocation.Discard)
                return "随机弃牌候选必须同时满足位置和所属方";
        }
        return null;
    }

    private static string? SpawnHandImplicitOutId(CardDatabase db)
    {
        foreach (Side side in new[] { Side.Left, Side.Right })
        {
            var (engine, state) = EmptyBoard(db);
            var source = state.CreateWithId("card_unit_432_infantry_regiment", side, 60, CardLocation.Discard, 0);
            var steps = new[] {
                new KismetStep(0, "call", "SpawnCardInHandBySide", new[] {
                    new KismetExpr { Int = (int)side }, new KismetExpr { Name = "card_event_supply_chain" },
                    new KismetExpr { Int = source.CardId }, new KismetExpr { Bool = true },
                    new KismetExpr { Bool = false }, new KismetExpr { Bool = false },
                    new KismetExpr { Str = "" }, new KismetExpr { Var = "campaign", Scope = "local" },
                    new KismetExpr { Int = 0 }, new KismetExpr { Var = "spawnedID", Scope = "local" }
                }, Array.Empty<int>(), null, null, -1, null, null),
                new KismetStep(1, "set", null, Array.Empty<KismetExpr>(), Array.Empty<int>(),
                    new KismetExpr { Math = "Add_IntInt", Args = new[] {
                        new KismetExpr { Var = "spawnedID", Scope = "local" }, new KismetExpr { Int = 1 }
                    } }, null, -1, "nextID", null),
                new KismetStep(2, "return", null, Array.Empty<KismetExpr>(), Array.Empty<int>(), null, null, -1, null, null)
            };
            var output = engine.Api.Vm.RunLocalProgramMulti(new KismetProgram(steps, 0),
                new EffectContext { Engine = engine, State = state, Self = source, Controller = side }, null, "spawnedID", "nextID");
            var spawned = state.Hand(side).Single(x => x.Name == "card_event_supply_chain");
            if (output.GetValueOrDefault("spawnedID") is not int id || id != spawned.CardId
                || Convert.ToInt32(output.GetValueOrDefault("nextID")) != id + 1 || source.KreditCost != source.Definition.Kredits)
                return "手牌生成调用必须写入整数新ID，不能留下空槽或写入卡对象";
        }
        return null;
    }

    private static string? DirectPlayBlockedDestination(CardDatabase db)
    {
        foreach (Side side in new[] { Side.Left, Side.Right })
        foreach (int mode in new[] { 0, 1, 2, 3 })
        foreach (bool restricted in new[] { false, true })
        {
            var (engine, state) = EmptyBoard(db);
            state.ActiveSide = side.Opposite();
            state.SetKredits(side, 4);
            if (mode == 0)
                for (int i = 0; i < 4; i++) state.CreateWithId("card_unit_432_infantry_regiment", side, 100 + i, side.HqOf(), i + 1);
            if (mode is 1 or 3)
                for (int i = 0; i < state.FrontlineCapacity; i++)
                    state.CreateWithId("card_unit_432_infantry_regiment", side, 110 + i, CardLocation.BoardFrontline, i);
            if (mode is 2 or 3) state.FrontlineOwner = side.Opposite();
            if (restricted) state.AddGameplayRestriction(side, GameplayRestrictionType.CannotDiscardAnyCardFromHand, 30, 2);
            var card = state.CreateWithId("card_unit_35th_mountain_rifles", side, 60, side.HandOf(), 7);
            var remaining = state.CreateWithId("card_unit_432_infantry_regiment", side, 61, side.HandOf(), 15);
            var discarded = state.CreateWithId(remaining.Name, side, 62, CardLocation.Discard, 17);
            int entered = card.EnteredPlayOnTurn, total = state.AllCards.Count();
            var trace = new List<string>();
            engine.Api.TriggerTrace = trace;
            var moved = state.CardMoved;
            int notifications = 0;
            state.CardMoved = (c, oldLocation, newLocation, ownerChange, reason) =>
            {
                if (c == card) notifications++;
                moved?.Invoke(c, oldLocation, newLocation, ownerChange, reason);
            };
            bool success = engine.PlayCardDirectlyFromHand(card, mode != 0, 9004, 1);
            var action = state.ActionLog.SelectMany(x => x.SubActions).SingleOrDefault(x => x.Name == "ZActionDiscardCard");
            if (success || card.Location != CardLocation.Discard || card.LocationNumber != 7 || discarded.LocationNumber != 17
                || remaining.LocationNumber != 0 || state.Kredits(side) != 4 || notifications != 0
                || card.EnteredPlayOnTurn != entered || state.AllCards.Count() != total || state.CardsPlayedThisTurn.Count != 0
                || action is null || action.Values.First(x => x.Name == "cardID").Value != card.CardId
                || action.Values.First(x => x.Name == "discarderID").Value != 0
                || action.Values.First(x => x.Name == "oldLocation").Text != (side == Side.Left ? "Hand_Left" : "Hand_Right")
                || trace.Any(x => x.StartsWith("OnAttemptedDiscard", StringComparison.Ordinal)))
                return $"直接出牌失败分支错误：方={side} 阻挡={mode} 限制={restricted} 结果={success} 位置={card.Location}";
        }
        return null;
    }

    private static string? DirectPlayForcedDiscardEvents(CardDatabase db)
    {
        foreach (Side side in new[] { Side.Left, Side.Right })
        foreach (bool suppressed in new[] { false, true })
        {
            var (engine, state) = EmptyBoard(db);
            state.ActiveSide = side;
            state.CreateWithId("card_unit_nakajima_b5n", side, 20, side.HqOf(), 1);
            for (int i = 0; i < 3; i++) state.CreateWithId("card_unit_432_infantry_regiment", side, 100 + i, side.HqOf(), i + 2);
            state.AddGameplayRestriction(side, GameplayRestrictionType.CannotDiscardAnyCardFromHand, 30, 2);
            var card = state.CreateWithId("card_event_supply_chain", side, 60, side.HandOf(), 7);
            if (suppressed) card.Keywords.Add(Keyword.Suppressed);
            var trace = new List<string>();
            engine.Api.TriggerTrace = trace;
            bool success = engine.PlayCardDirectlyFromHand(card, false, 9004, -1);
            var copies = state.Hand(side).Where(x => x.Name == card.Name).ToArray();
            bool own = trace.Any(x => x.StartsWith("OnSuccesfulDiscard →", StringComparison.Ordinal));
            if (success || card.Location != CardLocation.Discard || own == suppressed
                || copies.Length != (suppressed ? 0 : 2) || copies.Any(x => x.KreditCost != 1)
                || !trace.Any(x => x.StartsWith("OnOtherCardDiscarded → card_unit_nakajima_b5n#20", StringComparison.Ordinal)
                    && x.Contains("card_event_supply_chain#60", StringComparison.Ordinal)))
                return $"强制弃牌应保留成功与观察者事件：方={side} 抑制={suppressed} 副本={copies.Length} 费用={string.Join(",", copies.Select(x => x.KreditCost))} 自身={own}";
        }
        return null;
    }

    private static string? GotchaReceiptReplyIntegration(CardDatabase db)
    {
        foreach (bool handReply in new[] { false, true })
        {
            string name = handReply ? "card_unit_52_k" : "card_unit_m36_destroyer";
            using var probe = InstallSelectionDrawProbe(name, handReply ? "OnHandTargetSelected" : "OnPlayedFromHand");
            foreach (Side side in new[] { Side.Left, Side.Right })
            {
                var (engine, state) = EmptyBoard(db);
                var source = state.CreateWithId(name, side, 20, CardLocation.Discard, 0);
                var target = state.CreateWithId("card_unit_432_infantry_regiment", side, 30, side.HandOf(), 0);
                var first = state.CreateWithId("card_event_interception", side, 60, side.DeckOf(), 0);
                var second = state.CreateWithId(first.Name, side, 61, side.DeckOf(), 1);
                engine.Api.AddCustomGameplayTag(first, "autoplay");
                engine.Api.AddCustomGameplayTag(second, "autoplay");
                if (handReply)
                {
                    engine.PickHandTargetId = (_, _) => target.CardId;
                    engine.Api.InvokeByName("selectTargetFromHand", source, new object?[] { source.CardId },
                        new EffectContext { Engine = engine, State = state, Self = source, Controller = side }, out _);
                }
                else
                {
                    source.ExtraPlayTriggers = 1;
                    engine.Api.DrawChosenCardToHand(source, first);
                }
                if (first.GotchaActivated != 1 || first.Location != side.HandOf()
                    || engine.Api.JsonGetInt(first, "kreditsPayed") != 1 || second.GotchaActivated != 0
                    || second.Location != (handReply ? side.DeckOf() : side.HandOf())
                    || !state.GetAutoPlayCards().SequenceEqual(handReply ? Array.Empty<int>() : new[] { 61 }))
                    return $"选择回复未正确应用本批Gotcha通知：方={side} 手牌回复={handReply}";
            }
        }
        return null;
    }

    private static string? GotchaReceiptActionIntegration(CardDatabase db)
    {
        foreach (Side side in new[] { Side.Left, Side.Right })
        foreach (int route in new[] { 0, 1, 2, 3, 4 })
        {
            var (engine, state) = EmptyBoard(db);
            state.Turn = 2;
            state.ActiveSide = side;
            state.SetMaxKredits(side, 10);
            state.SetKredits(side, 10);
            var unit = state.CreateWithId("card_unit_432_infantry_regiment", side, 20,
                route == 4 ? CardLocation.BoardFrontline : side.HqOf(), route == 4 ? 0 : 1);
            unit.EnteredPlayOnTurn = 0;
            var card = state.CreateWithId("card_event_interception", side, 60,
                route <= 1 ? side.DeckOf() : side.HandOf(), 0);
            int entered = card.EnteredPlayOnTurn;
            engine.Api.AddCustomGameplayTag(card, "autoplay"); // Controlled queue-entry tag.
            state.CreateWithId(unit.Name, side, 61, side.DeckOf(), 1);
            if (route == 2) state.CreateWithId(unit.Name, side.Opposite(), 63, side.Opposite().DeckOf(), 0);
            if (route >= 2) state.AddAutoPlayCards(card.CardId);
            bool success = true;
            if (route == 0) engine.StartTurn(side, draw: true);
            else if (route == 1)
            {
                var order = state.CreateWithId("card_event_convoy_175", side, 70, side.HandOf(), 0);
                success = engine.PlayCard(order);
            }
            else if (route == 2) engine.EndTurn(side);
            else if (route == 3) success = engine.MoveUnit(unit, 0);
            else success = engine.Attack(unit, state.Hq(side.Opposite()));
            if (!success || card.Location != side.HandOf() || card.GotchaActivated != 1
                || engine.Api.JsonGetInt(card, "kreditsPayed") != 1 || card.EnteredPlayOnTurn != entered
                || state.GetAutoPlayCards().Length != 0 || state.CardsPlayedThisTurn.Any(x => x.CardId == card.CardId))
                return $"普通行动未完成Gotcha接收阶段：方={side} 路径={route} 激活={card.GotchaActivated} 位置={card.Location} 已付={engine.Api.JsonGetInt(card, "kreditsPayed")} 进入={card.EnteredPlayOnTurn} 队列={state.GetAutoPlayCards().Length}";
        }
        return null;
    }

    private static string? GotchaReceiptBoundary(CardDatabase db)
    {
        foreach (Side side in new[] { Side.Left, Side.Right })
        foreach (bool active in new[] { false, true })
        foreach (bool tagged in new[] { false, true })
        foreach (int? paid in new int?[] { null, 3 })
        {
            var (engine, state) = EmptyBoard(db);
            state.Turn = 9;
            state.ActiveSide = side;
            state.SetKredits(side, 10);
            var other = state.CreateWithId("card_event_interception", side, 20, CardLocation.Discard, 0);
            other.GotchaActivated = 7;
            var card = state.CreateWithId(other.Name, side, 60, side.HandOf(), 7);
            card.GotchaActivated = active ? 5 : 0;
            card.EnteredPlayOnTurn = 6;
            if (paid is int amount) engine.Api.JsonSetInt(card, "kreditsPayed", amount);
            if (tagged) engine.Api.AddCustomGameplayTag(card, "autoplay");
            bool played = engine.PlayCard(card);
            int expected = active ? 10 + (paid ?? 0) : 10 - (tagged ? 0 : 1);
            if (!played || card.Location != side.HandOf() || card.LocationNumber != 7 || card.EnteredPlayOnTurn != 6
                || card.GotchaActivated != (active ? 0 : 8) || state.Kredits(side) != expected
                || engine.Api.JsonGetInt(card, "kreditsPayed") != (active ? paid ?? 0 : 1)
                || state.CardsPlayedThisTurn.Count != 0 || other.GotchaActivated != 7)
                return $"Gotcha普通出牌处理/接收错误：方={side} 激活={active} 标签={tagged} 已付={paid} 最终={card.Location}/{card.GotchaActivated}/{state.Kredits(side)}";
            var play = state.ActionLog.SelectMany(x => x.SubActions).SingleOrDefault(x => x.Name == "ZActionPlayCardFromHand");
            if (play is null || play.Values.First(x => x.Name == "cardID").Value != 60
                || play.Values.First(x => x.Name == "instigatorID").Value != 60
                || play.Values.First(x => x.Name == "locationNumber").Value != 7
                || play.Values.First(x => x.Name == "enterPlayOnTurn").Value != 9
                || play.Values.Any(x => x.Name == "playedDirectly"))
                return "Gotcha普通出牌通知应保留手牌编号、当前回合和隐式非直接标记";
        }
        return null;
    }

    private static string? GotchaReceiptBatchOrder(CardDatabase db)
    {
        foreach (Side side in new[] { Side.Left, Side.Right })
        foreach (bool duplicate in new[] { false, true })
        {
            var (engine, state) = EmptyBoard(db);
            state.ActiveSide = side;
            state.SetKredits(side, 10);
            var first = state.CreateWithId("card_event_interception", side, 60, side.HandOf(), 0);
            if (duplicate) state.AddAutoPlayCards(first.CardId);
            else
            {
                var second = state.CreateWithId(first.Name, side, 61, side.HandOf(), 1);
                var third = state.CreateWithId(first.Name, side, 62, side.HandOf(), 2);
                third.GotchaActivated = 9;
                engine.Api.JsonSetInt(third, "kreditsPayed", 3);
                state.AddAutoPlayCards(second.CardId);
                state.AddAutoPlayCards(third.CardId);
            }
            bool played = engine.PlayCard(first);
            var ids = state.ActionLog.SelectMany(x => x.SubActions).Where(x => x.Name == "ZActionPlayCardFromHand")
                .Select(x => x.Values.First(v => v.Name == "cardID").Value).ToArray();
            if (!played || first.Location != side.HandOf() || state.CardsPlayedThisTurn.Count != 0
                || first.GotchaActivated != (duplicate ? 0 : 10) || state.Kredits(side) != (duplicate ? 8 : 11)
                || !ids.SequenceEqual(duplicate ? new[] { 60, 60 } : new[] { 60, 61, 62 })
                || !duplicate && (state.ById(61)!.GotchaActivated != 11 || state.ById(62)!.GotchaActivated != 0))
                return $"Gotcha应先完成整批费用再依序接收：方={side} 重复通知={duplicate} 资源={state.Kredits(side)} 激活={first.GotchaActivated}";
        }
        return null;
    }

    private static string? GotchaReceiptUsesCurrentState(CardDatabase db)
    {
        foreach (Side side in new[] { Side.Left, Side.Right })
        foreach (bool leaveHand in new[] { false, true })
        foreach (bool directly in new[] { false, true })
        {
            var (engine, state) = EmptyBoard(db);
            state.SetKredits(side, 10);
            var other = state.CreateWithId("card_event_interception", side, 20, CardLocation.Discard, 0);
            other.GotchaActivated = 7;
            var card = state.CreateWithId(other.Name, side, 60, side.HandOf(), 0);
            engine.Api.JsonSetInt(card, "kreditsPayed", 9);
            if (directly) engine.PlayCardDirectlyFromHand(card, false, 9004, -1);
            else { state.AddAutoPlayCards(card.CardId); engine.ExecuteAutoPlayCards(); }
            if (card.GotchaActivated != (directly ? 8 : 0)) return "接收之前不能提前切换普通通知的激活号";
            if (leaveHand) state.Move(card, CardLocation.Discard, notifyMoved: false);
            card.KreditCost = 3; // Controlled mutation between rule and receipt stages.
            engine.ApplyPendingGotchaPlayReceipts();
            if (card.GotchaActivated != 8 || engine.Api.JsonGetInt(card, "kreditsPayed") != (directly ? 9 : 3)
                || card.Location != (leaveHand ? CardLocation.Discard : side.HandOf()))
                return "接收应读取当前费用且无手牌门，本地直接出牌应跳过重复切换";
            engine.ApplyPendingGotchaPlayReceipts();
            if (card.GotchaActivated != 8) return "接收队列排空后不能重复切换";
        }
        return null;
    }

    private static string? DirectGotchaBoundary(CardDatabase db)
    {
        foreach (Side side in new[] { Side.Left, Side.Right })
        foreach (bool active in new[] { false, true })
        foreach (bool full in new[] { false, true })
        foreach (bool frontline in new[] { false, true })
        foreach (int requestedNumber in new[] { -1, 0, 17 })
        {
            var (engine, state) = EmptyBoard(db);
            state.Turn = 9;
            state.ActiveSide = side.Opposite();
            state.SetMaxKredits(side, 4);
            state.SetKredits(side, 4);
            if (full)
                for (int i = 0; i < 4; i++)
                    state.CreateWithId("card_unit_432_infantry_regiment", side, 100 + i, side.HqOf(), i + 1);
            state.CreateWithId("card_unit_432_infantry_regiment", side.Opposite(), 110, CardLocation.BoardFrontline, 0);
            state.FrontlineOwner = side.Opposite();
            var other = state.CreateWithId("card_event_interception", side, 20, CardLocation.Discard, 0);
            other.GotchaActivated = 7;
            var enemy = state.CreateWithId(other.Name, side.Opposite(), 21, side.Opposite().HandOf(), 0);
            enemy.GotchaActivated = 99;
            var card = state.CreateWithId(other.Name, side, 60, side.HandOf(), 7);
            card.GotchaActivated = active ? 5 : 0;
            card.EnteredPlayOnTurn = 6;
            card.CardSeen = true;
            engine.Api.JsonSetInt(card, "kreditsPayed", 3);
            engine.Api.JsonSetInt(card, "countdown_timer", 2);
            var moved = state.CardMoved;
            int moves = 0;
            state.CardMoved = (c, oldLocation, newLocation, ownerChange, reason) =>
            {
                if (c == card) moves++;
                moved?.Invoke(c, oldLocation, newLocation, ownerChange, reason);
            };
            var trace = new List<string>();
            engine.Api.TriggerTrace = trace;
            bool success = engine.PlayCardDirectlyFromHand(card, frontline, 9004, requestedNumber);
            if (!success || card.GotchaActivated != (active ? 0 : 8) || card.Location != side.HandOf()
                || card.LocationNumber != 7 || card.EnteredPlayOnTurn != 6 || !card.CardSeen
                || state.Kredits(side) != 4 || state.MaxKredits(side) != 4 || moves != 0
                || state.CardsPlayedThisTurn.Count != 0 || trace.Count != 0
                || engine.Api.JsonGetInt(card, "kreditsPayed") != 3 || engine.Api.JsonGetInt(card, "countdown_timer") != 2
                || other.GotchaActivated != 7 || enemy.GotchaActivated != 99)
                return $"Gotcha直接出牌分支错误：方={side} 激活={active} 满员={full} 前线={frontline} 请求编号={requestedNumber} 实际={card.Location}/{card.GotchaActivated}";
        }
        return null;
    }

    private static string? AutoPlayGotchaCostBranch(CardDatabase db)
    {
        foreach (Side side in new[] { Side.Left, Side.Right })
        foreach (bool active in new[] { false, true })
        foreach (bool tagged in new[] { false, true })
        foreach (int? paid in new int?[] { null, 0, 3, -2, 30 })
        {
            var (engine, state) = EmptyBoard(db);
            state.Turn = 9;
            state.SetMaxKredits(side, 4);
            state.SetKredits(side, 10);
            var card = state.CreateWithId("card_event_interception", side, 60, side.HandOf(), 7);
            card.GotchaActivated = active ? 5 : 0;
            card.EnteredPlayOnTurn = 6;
            if (paid is int amount) engine.Api.JsonSetInt(card, "kreditsPayed", amount);
            if (tagged) engine.Api.AddCustomGameplayTag(card, "autoplay");
            var moved = state.CardMoved;
            int moves = 0;
            state.CardMoved = (c, oldLocation, newLocation, ownerChange, reason) =>
            {
                if (c == card) moves++;
                moved?.Invoke(c, oldLocation, newLocation, ownerChange, reason);
            };
            state.AddAutoPlayCards(card.CardId);
            engine.ExecuteAutoPlayCards();
            int expected = active ? Math.Clamp(10 + (paid ?? 0), 0, 24) : 10 - (tagged ? 0 : card.KreditCost);
            if (card.Location != side.HandOf() || card.LocationNumber != 7 || card.GotchaActivated != (active ? 5 : 0)
                || card.EnteredPlayOnTurn != 6 || moves != 0 || state.CardsPlayedThisTurn.Count != 0
                || state.Kredits(side) != expected || state.MaxKredits(side) != 4 || state.GetAutoPlayCards().Length != 0
                || engine.Api.JsonGetInt(card, "kreditsPayed") != (paid ?? 0))
                return $"Gotcha自动消费错误：方={side} 激活={active} 标签={tagged} 退款={paid} 位置={card.Location} 指挥点={state.Kredits(side)}";
            var change = state.ActionLog.SelectMany(x => x.SubActions).LastOrDefault(x => x.Name == "ZActionChangeKredits");
            if ((change is not null) != (active || !tagged)
                || change is not null && (change.Values.First(x => x.Name == "triggerCardID").Value != 60
                    || change.Values.First(x => x.Name == "oldKredits").Value != 10
                    || change.Values.First(x => x.Name == "newKredits").Value != expected
                    || change.Values.First(x => x.Name == "oldMaxKredits").Value != 4
                    || change.Values.First(x => x.Name == "newMaxKredits").Value != 4))
                return "Gotcha消费费用通知未保留来源与前后资源";
            int logCount = state.ActionLog.Count;
            engine.ExecuteAutoPlayCards();
            if (state.Kredits(side) != expected || state.ActionLog.Count != logCount) return "空队列重复调用不应再次退款";
        }
        return null;
    }

    private static string? AutoPlayActivatedFieldRefund(CardDatabase db)
    {
        foreach (Side side in new[] { Side.Left, Side.Right })
        foreach (bool tagged in new[] { false, true })
        {
            var (engine, state) = EmptyBoard(db);
            state.SetKredits(side, 10);
            var card = state.CreateWithId("card_unit_432_infantry_regiment", side, 60, side.HandOf(), 0);
            card.GotchaActivated = 5; // Controlled field probe; not a normal card state.
            engine.Api.JsonSetInt(card, "kreditsPayed", 3);
            if (tagged) engine.Api.AddCustomGameplayTag(card, "autoplay");
            state.AddAutoPlayCards(card.CardId);
            engine.ExecuteAutoPlayCards();
            if (!card.Location.IsBoard() || card.GotchaActivated != 5 || state.Kredits(side) != 13)
                return "PlayCardFromHand退款分支只看激活字段，不应另加类型/标签限制或再扣费";
        }
        return null;
    }

