            var resistance = state.CreateWithId("card_event_resistance_new", Side.Left, 60, CardLocation.HandLeft, 0);
            state.AddAutoPlayCards(60);
            bool completed;
            if (route == 0)
            {
                var unit = state.CreateWithId("card_unit_432_infantry_regiment", Side.Left, 61, CardLocation.HandLeft, 1);
                completed = engine.PlayCard(unit);
            }
            else if (route == 1) completed = engine.MoveUnit(state.Hq(Side.Left), 0);
            else completed = engine.Attack(state.Hq(Side.Left), state.Hq(Side.Right));
            if (completed || resistance.Location != CardLocation.HandLeft || !state.GetAutoPlayCards().SequenceEqual(new[] { 60 }))
                return "被本地合法性检查拒绝的行动不应消费待执行队列";
        }
        return null;
    }

    private static string? AutoPlayResistanceChain(CardDatabase db)
    {
        foreach (Side side in new[] { Side.Left, Side.Right })
        {
            var (engine, state) = EmptyBoard(db);
            state.Turn = 2;
            state.SetMaxKredits(side, 10);
            state.SetKredits(side, 5);
            var unit = state.CreateWithId("card_unit_432_infantry_regiment", side, 20, side.HqOf(), 1);
            var first = state.CreateWithId("card_event_resistance_new", side, 70, side.HandOf(), 0);
            var second = state.CreateWithId(first.Name, side, 60, side.DeckOf(), 0);
            var last = state.CreateWithId(unit.Name, side, 61, side.DeckOf(), 1);
            state.AddAutoPlayCards(first.CardId);
            int hp = state.HqDefense(side);
            engine.ExecuteAutoPlayCards();
            var plays = state.CardsPlayedThisTurn.Where(x => x.Name == first.Name).Select(x => x.CardId).ToArray();
            if (first.Location != CardLocation.Discard || second.Location != CardLocation.Discard
                || last.Location != side.HandOf() || state.GetAutoPlayCards().Length != 0
                || state.HqDefense(side) != hp - 2 || state.Kredits(side) != 3 || unit.PinnedTurns <= 0
                || !plays.SequenceEqual(new[] { 70, 60 }))
                return $"RESISTANCE连锁消费错误：方={side} HQ={state.HqDefense(side)} 指挥点={state.Kredits(side)} 次数={plays.Length}";
        }
        return null;
    }

    private static string? AutoPlayConsumerGate(CardDatabase db)
    {
        foreach (Side side in new[] { Side.Left, Side.Right })
        foreach (bool tagged in new[] { false, true })
        {
            var (engine, state) = EmptyBoard(db);
            state.Turn = 2;
            state.SetMaxKredits(side, 10);
            state.SetKredits(side, 10);
            var hand = state.CreateWithId("card_unit_432_infantry_regiment", side, 60, side.HandOf(), 0);
            var deck = state.CreateWithId(hand.Name, side, 61, side.DeckOf(), 0);
            var discarded = state.CreateWithId(hand.Name, side, 62, CardLocation.Discard, 0);
            if (tagged) engine.Api.AddCustomGameplayTag(hand, "autoplay");
            int cost = hand.KreditCost;
            foreach (int id in new[] { 9999, deck.CardId, hand.CardId, discarded.CardId }) state.AddAutoPlayCards(id);
            engine.ExecuteAutoPlayCards();
            if (!hand.Location.IsBoard() || deck.Location != side.DeckOf() || discarded.Location != CardLocation.Discard
                || state.GetAutoPlayCards().Length != 0 || state.Kredits(side) != 10 - (tagged ? 0 : cost))
                return $"自动打出消费位置/费用门错误：方={side} 标签={tagged}";
            engine.ExecuteAutoPlayCards(); // Empty queue is a no-op.
            if (state.Kredits(side) != 10 - (tagged ? 0 : cost)) return "空自动打出队列重复执行扣费";
        }
        return null;
    }

    private static string? DrawAutoPlayQueue(CardDatabase db)
    {
        foreach (Side side in new[] { Side.Left, Side.Right })
        foreach (int route in new[] { 0, 1, 2 })
        foreach (bool full in new[] { false, true })
        foreach (int tagMode in new[] { 0, 1, 2, 3 })
        {
            var (engine, state) = EmptyBoard(db);
            Side recipient = route == 1 ? side.Opposite() : side;
            if (full)
                for (int i = 0; i < GameState.HandCapacity; i++)
                    state.CreateWithId("card_unit_432_infantry_regiment", recipient, 100 + i, recipient.HandOf(), i);
            var card = state.CreateWithId(tagMode <= 1 ? "card_event_resistance_new" : "card_unit_432_infantry_regiment",
                side, 60, side.DeckOf(), 0);
            if (tagMode == 1) card.RemovedGameplayTags.Add("autoplay");
            if (tagMode == 3) engine.Api.AddCustomGameplayTag(card, "autoplay");
            if (route == 2) engine.Api.InvokeByName("DrawSpecificCardFromDeckBySide", card,
                new object?[] { 0, card.CardId, (int)side, false },
                new EffectContext { Engine = engine, State = state, Controller = side }, out _);
            else engine.DrawCard(side, opponentDraw: route == 1);
            int[] expected = !full && tagMode is 0 or 3 ? new[] { 60 } : Array.Empty<int>();
            if (!state.GetAutoPlayCards().SequenceEqual(expected))
                return $"自动打出入队错误：方={side} 路径={route} 满手={full} 标签={tagMode}";
        }
        return null;
    }

    private static string? DrawAutoPlayAfterEvents(CardDatabase db)
    {
        foreach (bool initiallyTagged in new[] { false, true })
        foreach (bool leaveHand in new[] { false, true })
        {
            var (engine, state) = EmptyBoard(db);
            string name = initiallyTagged ? "card_event_resistance_new" : "card_unit_51e_regiment";
            var card = state.CreateWithId(name, Side.Left, 30, CardLocation.DeckLeft, 0);
            bool callback = false;
            using var probe = InstallDrawReentryProbe(state, () =>
            {
                callback = true;
                if (initiallyTagged) card.RemovedGameplayTags.Add("autoplay");
                else engine.Api.AddCustomGameplayTag(card, "autoplay");
                if (leaveHand) state.Move(card, CardLocation.Discard, notifyMoved: false);
            }, name);
            engine.DrawCard(Side.Left);
            if (!callback || !state.GetAutoPlayCards().SequenceEqual(initiallyTagged ? Array.Empty<int>() : new[] { 30 }))
                return $"自动打出应读取事件后的标签且不加位置门：原标签={initiallyTagged} 离手={leaveHand}";
        }
        {
            var (_, state) = EmptyBoard(db);
            foreach (int id in new[] { 9, 2, 9, 0, -7, 2 }) state.AddAutoPlayCards(id);
            var copied = state.GetAutoPlayCards();
            var snapshot = state.Snapshot();
            copied[0] = 888;
            if (!state.GetAutoPlayCards().SequenceEqual(new[] { 9, 2, 0, -7 })
                || !snapshot.AutoPlayerCardIds.SequenceEqual(new[] { 9, 2, 0, -7 }))
                return "自动打出队列应保首次插入顺序、去重且返回副本，不自行过滤ID";
            state.ClearAutoPlayCards();
            state.AddAutoPlayCards(2);
            if (!state.GetAutoPlayCards().SequenceEqual(new[] { 2 }) || snapshot.AutoPlayerCardIds.Length != 4)
                return "清空队列不应改写历史快照，清空后ID应可重新入队";
        }
        return null;
    }

    private static string? DrawWithoutLocationMoved(CardDatabase db)
    {
        foreach (Side deckSide in new[] { Side.Left, Side.Right })
        foreach (int route in new[] { 0, 1, 2 })
        foreach (bool full in new[] { false, true })
        {
            var (engine, state) = EmptyBoard(db);
            Side recipient = route == 1 ? deckSide.Opposite() : deckSide;
            state.CreateWithId("card_unit_spitfire_mk_ii", deckSide, 20, deckSide.HqOf(), 1);
            if (full)
                for (int i = 0; i < GameState.HandCapacity; i++)
                    state.CreateWithId("card_unit_432_infantry_regiment", recipient, 100 + i, recipient.HandOf(), i);
            var card = state.CreateWithId("card_unit_13e_dragons", deckSide, 60, deckSide.DeckOf(), 0);
            var trace = new List<string>();
            engine.Api.TriggerTrace = trace;
            var moved = state.CardMoved;
            int notifications = 0;
            state.CardMoved = (c, oldLocation, newLocation, ownerChange, reason) =>
            {
                if (c == card) notifications++;
                moved?.Invoke(c, oldLocation, newLocation, ownerChange, reason);
            };
            if (route == 2) engine.Api.InvokeByName("DrawSpecificCardFromDeckBySide", card,
                new object?[] { 0, card.CardId, (int)deckSide, false },
                new EffectContext { Engine = engine, State = state, Controller = deckSide }, out _);
            else engine.DrawCard(deckSide, opponentDraw: route == 1);
            bool ownDraw = trace.Any(x => x.StartsWith("OnCardDrawnFromDeck →", StringComparison.Ordinal));
            if (notifications != 0 || ownDraw == full
                || trace.Any(x => x.StartsWith("OnCardLocationMoved →", StringComparison.Ordinal)
                    || x.StartsWith("OnOtherCardLocationMoved →", StringComparison.Ordinal)))
                return $"抽牌误发位置事件或漏自身抽牌：方={deckSide} 路径={route} 满手={full} 通知={notifications}";
            // Positive control: a genuine subsequent zone move still dispatches T47.
            trace.Clear();
            state.Move(card, CardLocation.NotAvailable);
            if (notifications != 1 || !trace.Any(x => x.StartsWith("OnOtherCardLocationMoved → card_unit_spitfire_mk_ii#20", StringComparison.Ordinal)))
                return "位置事件正向对照未触发，不能证明抽牌路径的事件隔离";
        }
        return null;
    }

    private static string? InitialScryLiveFiltering(CardDatabase db)
    {
        const string name = "card_unit_41st_infantry_regiment", filter = "FilterCardsToScry", marker = "card_unit_routed_troops";
        if (KismetLibrary.Default?.Find(name)?.Locals is not IDictionary<string, IReadOnlyList<KismetStep>> locals
            || locals.ContainsKey(filter)) return "无法安装候选展示重入探针";
        locals[filter] = new[] {
            new KismetStep(0, "set", null, Array.Empty<KismetExpr>(), Array.Empty<int>(), new KismetExpr { Math = "BooleanAND", Args = new[] {
                new KismetExpr { Var = "_auditOfferValid", Context = new KismetExpr { Var = "card" } },
                new KismetExpr { Var = "_auditOfferAllow", Scope = "instance" }
            } }, null, -1, "isValid", null) { DestinationScope = "local" },
            new KismetStep(1, "set", null, Array.Empty<KismetExpr>(), Array.Empty<int>(),
                new KismetExpr { Var = "cardID", Context = new KismetExpr { Var = "card" } }, null, -1, "_auditOfferCurrent", null) { DestinationScope = "instance" },
            new KismetStep(2, "call", "SpawnCardInHandBySide", new[] { new KismetExpr { Int = (int)Side.Right },
                new KismetExpr { Str = marker }, new KismetExpr { Int = 30 } }, Array.Empty<int>(), null, null, -1, null, null),
            new KismetStep(3, "return", null, Array.Empty<KismetExpr>(), Array.Empty<int>(), null, null, -1, null, null),
        };
        try
        {
            foreach (Side side in new[] { Side.Left, Side.Right })
            foreach (bool full in new[] { false, true })
            foreach (int mode in Enumerable.Range(0, 8))
            {
                var (engine, state) = EmptyBoard(db);
                var original = state.CreateWithId(name, side, 30, CardLocation.Discard, 0);
                original.BlueprintVariables["_auditOfferAllow"] = true;
                if (full) for (int i = 0; i < 9; i++) state.CreateWithId(PlainUnit, side, 100 + i, side.HandOf(), i);
                for (int i = 0; i < (mode == 0 ? 2 : 6); i++) state.CreateWithId(PlainUnit, side, 60 + i, side.DeckOf(), i * 4)
                    .BlueprintVariables["_auditOfferValid"] = mode == 0 ? i != 1 : mode == 1 ? i is not (2 or 3) : mode == 4 ? i != 1 : true;
                if (mode == 5) for (int i = 0; i < 6; i++) state.CreateWithId(PlainUnit, side.Opposite(), 70 + i, side.Opposite().DeckOf(), i * 4)
                    .BlueprintVariables["_auditOfferValid"] = true;
                var visits = new List<int>(); bool mutated = false; CardInstance? replacement = null;
                state.CardCreated += card => {
                    if (card.Name != marker) return;
                    card.Location = CardLocation.Discard;
                    var receiver = state.ById(30)!;
                    int current = Convert.ToInt32(receiver.BlueprintVariables["_auditOfferCurrent"]); visits.Add(current);
                    if (mutated || current != (mode == 6 ? 60 : 61) || mode == 7) return;
                    mutated = true;
                    if (mode == 0) for (int i = 0; i < 2; i++) state.CreateWithId(PlainUnit, side, 62 + i, side.DeckOf(), 20 + i)
                        .BlueprintVariables["_auditOfferValid"] = true;
                    if (mode == 1) { state.ById(64)!.Location = CardLocation.Discard; state.ById(65)!.Location = CardLocation.Discard; }
                    if (mode == 2) { var a = state.ById(61)!; var b = state.ById(62)!; (a.LocationNumber, b.LocationNumber) = (b.LocationNumber, a.LocationNumber); }
                    if (mode == 3) { state.ById(61)!.Location = CardLocation.Discard; state.CreateWithId(PlainUnit, side, 90, side.DeckOf(), 4).BlueprintVariables["_auditOfferValid"] = false; }
                    if (mode == 4) foreach (var item in state.Deck(side).Where(x => x.CardId != 60)) item.Location = CardLocation.Discard;
                    if (mode == 5) state.ChangeOwner(original, side.Opposite(), normalize: false);
                    if (mode == 6) { state.Remove(original); replacement = state.CreateWithId(name, side, 30, CardLocation.Discard, 0); replacement.BlueprintVariables["_auditOfferAllow"] = false; }
                };
                int[] expectedVisits = mode switch {
                    0 => new[] { 60, 61, 62, 63 }, 1 => new[] { 60, 61, 62, 63 }, 2 => new[] { 60, 61, 61 },
                    5 => new[] { 60, 61, 72 }, 6 => new[] { 60, 61, 62, 63, 64, 65 },
                    4 => new[] { 60, 61 }, _ => new[] { 60, 61, 62 },
                };
                int[] expectedOffers = mode switch {
                    0 => new[] { 60, 62, 63 }, 1 => new[] { 60, 61 }, 2 => new[] { 60, 62, 61 },
                    3 => new[] { 60, 90, 62 }, 5 => new[] { 60, 71, 72 }, 4 or 6 => new[] { 60 }, _ => new[] { 60, 61, 62 },
                };
                var offered = new List<int>(); int replies = 0;
                engine.ChooseSpawnCard = (_, cards) => { replies++; offered.AddRange(cards.Select(x => x.CardId)); return null; };
                engine.Api.InvokeByName("selectCardToDraw", original, new object?[] { 30, true, false, null },
                    new EffectContext { Engine = engine, State = state, Self = original, Controller = side }, out _);
                var draws = state.ActionLog.SelectMany(x => x.SubActions).Where(x => x.Name == "ZActionDrawCardFromDeck").ToArray();
                bool singleton = expectedOffers.Length == 1;
                if (!visits.SequenceEqual(expectedVisits) || replies != (singleton ? 0 : 1)
                    || !singleton && !offered.SequenceEqual(expectedOffers) || draws.Length != (singleton ? 1 : 0)
                    || singleton && (draws[0].Values.First(x => x.Name == "instigatorID").Value != 30
                        || state.ById(60)!.Location != (full ? CardLocation.Discard : side.HandOf()))
                    || state.UnimplementedCalls.Keys.Any(x => x.StartsWith("<selectCardToDraw:", StringComparison.Ordinal)))
                    return $"初次候选重入错误：{side}/full={full}/mode={mode}/visits={string.Join(",", visits)}/offers={string.Join(",", offered)}";
            }
            foreach (Side side in new[] { Side.Left, Side.Right })
            foreach (bool removeReceiver in new[] { false, true })
            {
                var (engine, state) = EmptyBoard(db);
                var source = state.CreateWithId(name, side, 30, CardLocation.Discard, 0); source.BlueprintVariables["_auditOfferAllow"] = true;
                for (int i = 0; i < 4; i++) state.CreateWithId(PlainUnit, side, 60 + i, side.DeckOf(), i).BlueprintVariables["_auditOfferValid"] = true;
                state.CardCreated += card => { if (card.Name != marker) return; card.Location = CardLocation.Discard;
                    if (removeReceiver) state.Remove(source); else foreach (var item in state.Deck(side)) item.Location = CardLocation.Discard;
                };
                int replies = 0; engine.ChooseSpawnCard = (_, _) => { replies++; return null; };
                engine.Api.InvokeByName("selectCardToDraw", source, new object?[] { 30, true, false, null },
                    new EffectContext { Engine = engine, State = state, Self = source, Controller = side }, out _);
                string gap = removeReceiver ? "<selectCardToDraw:missing-filter-receiver>" : "<selectCardToDraw:post-filter-index-object-output>";
                if (state.UnimplementedCalls.GetValueOrDefault(gap) != 1 || replies != 0
                    || state.ActionLog.SelectMany(x => x.SubActions).Any(x => x.Name == "ZActionDrawCardFromDeck"))
                    return "不可表示的展示回调缺口应明确记账，不能伪造空候选完成";
            }
            return null;
        }
        finally { locals.Remove(filter); }
    }

    private static string? MultiScryLiveFiltering(CardDatabase db)
    {
        const string name = "card_unit_typhoon_mk_ib", filter = "FilterCardsToScry", marker = "card_unit_routed_troops";
        if (KismetLibrary.Default?.Find(name)?.Locals is not IDictionary<string, IReadOnlyList<KismetStep>> locals
            || locals.ContainsKey(filter)) return "无法安装实时牌库过滤探针";
        locals[filter] = new[] {
            new KismetStep(0, "set", null, Array.Empty<KismetExpr>(), Array.Empty<int>(),
                new KismetExpr { Var = "_auditLiveScryValid", Context = new KismetExpr { Var = "card" } }, null, -1, "isValid", null) { DestinationScope = "local" },
            new KismetStep(1, "set", null, Array.Empty<KismetExpr>(), Array.Empty<int>(),
                new KismetExpr { Var = "cardID", Context = new KismetExpr { Var = "card" } }, null, -1, "_auditLiveScryCurrent", null) { DestinationScope = "instance" },
            new KismetStep(2, "call", "SpawnCardInHandBySide", new[] { new KismetExpr { Int = (int)Side.Right },
                new KismetExpr { Str = marker }, new KismetExpr { Int = 30 } }, Array.Empty<int>(), null, null, -1, null, null),
            new KismetStep(3, "return", null, Array.Empty<KismetExpr>(), Array.Empty<int>(), null, null, -1, null, null),
        };
        try
        {
            foreach (Side side in new[] { Side.Left, Side.Right })
            foreach (bool full in new[] { false, true })
            foreach (int triggerIndex in new[] { 1, 4 })
            foreach (bool predicate in new[] { false, true })
            foreach (int mutation in Enumerable.Range(0, 4))
            {
                var (engine, state) = EmptyBoard(db);
                var source = state.CreateWithId(name, side, 30, CardLocation.Discard, 0);
                if (full) for (int i = 0; i < 9; i++) state.CreateWithId(PlainUnit, side, 100 + i, side.HandOf(), i);
                var flags = Enumerable.Range(60, 6).ToDictionary(id => id, _ => true);
                int triggerId = 60 + triggerIndex; flags[triggerId] = predicate; flags[90] = !predicate;
                for (int i = 0; i < 6; i++) state.CreateWithId(PlainUnit, side, 60 + i, side.DeckOf(), i * 4)
                    .BlueprintVariables["_auditLiveScryValid"] = flags[60 + i];
                var expectedPhysical = Enumerable.Range(60, 6).ToList();
                if (mutation == 0) { expectedPhysical.Add(90); flags[90] = true; }
                if (mutation == 1) expectedPhysical.Remove(65);
                if (mutation == 2) (expectedPhysical[triggerIndex], expectedPhysical[triggerIndex + 1]) = (expectedPhysical[triggerIndex + 1], expectedPhysical[triggerIndex]);
                if (mutation == 3) expectedPhysical[triggerIndex] = 90;
                var expectedVisits = expectedPhysical.ToArray(); expectedVisits[triggerIndex] = triggerId;
                var expected = new List<int>(); int accepted = 0;
                for (int i = 0; i < expectedPhysical.Count; i++)
                {
                    bool valid = i == triggerIndex ? predicate : flags[expectedVisits[i]];
                    if (valid && accepted < 3) expected.Insert(accepted++, expectedPhysical[i]); else expected.Add(expectedPhysical[i]);
                }
                var displaced = expected.Take(3).Where(id => id != 60).ToArray();
                foreach (int id in displaced) { expected.Remove(id); expected.Add(id); }
                bool mutated = false; var visited = new List<int>();
                state.CardCreated += card => {
                    if (card.Name != marker) return;
                    card.Location = CardLocation.Discard;
                    int current = Convert.ToInt32(source.BlueprintVariables["_auditLiveScryCurrent"]); visited.Add(current);
                    if (current != triggerId || mutated) return;
                    mutated = true;
                    if (mutation == 0) state.CreateWithId(PlainUnit, side, 90, side.DeckOf(), 100).BlueprintVariables["_auditLiveScryValid"] = true;
                    if (mutation == 1) state.ById(65)!.Location = CardLocation.Discard;
                    if (mutation == 2) { var a = state.ById(triggerId)!; var b = state.ById(triggerId + 1)!; (a.LocationNumber, b.LocationNumber) = (b.LocationNumber, a.LocationNumber); }
                    if (mutation == 3) {
                        int number = state.ById(triggerId)!.LocationNumber; state.ById(triggerId)!.Location = CardLocation.Discard;
                        state.CreateWithId(PlainUnit, side, 90, side.DeckOf(), number).BlueprintVariables["_auditLiveScryValid"] = !predicate;
                    }
                };
                var chosen = state.ById(60)!;
                engine.Api.DrawChosenCardToHand(source, chosen);
                var receipt = state.ActionLog.SelectMany(x => x.SubActions).SingleOrDefault(x => x.Name == "ZActionNewDeck");
                if (!mutated || !visited.SequenceEqual(expectedVisits) || receipt?.Values.First(x => x.Name == "cards").Text != string.Join(";", expected)
                    || !state.Deck(side).Select(x => x.CardId).SequenceEqual(expected.Skip(1))
                    || chosen.Location != (full ? CardLocation.Discard : side.HandOf())
                    || state.UnimplementedCalls.Keys.Any(x => x.StartsWith("<ExecuteScryingEffectBySide:", StringComparison.Ordinal)))
                    return $"过滤实时重入错误：{side}/{full}/index={triggerIndex}/valid={predicate}/mutation={mutation}/visits={string.Join(",", visited)}";
            }
            foreach (Side side in new[] { Side.Left, Side.Right })
            foreach (int mode in new[] { 0, 1 })
            {
                var (engine, state) = EmptyBoard(db);
                var source = state.CreateWithId(name, side, 30, CardLocation.Discard, 0);
                for (int i = 0; i < 4; i++) state.CreateWithId(PlainUnit, side, 60 + i, side.DeckOf(), i)
                    .BlueprintVariables["_auditLiveScryValid"] = true;
                bool changed = false;
                state.CardCreated += card => {
                    if (card.Name != marker) return;
                    card.Location = CardLocation.Discard;
                    int current = Convert.ToInt32(source.BlueprintVariables["_auditLiveScryCurrent"]);
                    if (changed || current != (mode == 0 ? 60 : 61)) return;
                    changed = true;
                    if (mode == 0) foreach (var item in state.Deck(side)) item.Location = CardLocation.Discard;
                    else state.ById(60)!.Location = CardLocation.Discard;
                };
                var result = engine.Api.DrawChosenCardToHand(source, state.ById(60));
                string gap = mode == 0 ? "<ExecuteScryingEffectBySide:post-filter-index-default-ID>" : "<ExecuteScryingEffectBySide:independent-ID-array-required>";
                if (!changed || result is not null || state.UnimplementedCalls.GetValueOrDefault(gap) != 1
                    || state.ActionLog.SelectMany(x => x.SubActions).Any(x => x.Name is "ZActionNewDeck" or "ZActionDrawCardFromDeck"))
                    return $"不可表示的原生牌库状态未明确记账：{side}/mode={mode}";
            }
            return null;
        }
        finally { locals.Remove(filter); }
    }

    private static string? MultiScryReplyContract(CardDatabase db)
    {
        const string name = "card_unit_51e_regiment", filter = "FilterCardsToScry", selected = "OnHandTargetSelected";
        const string watcherName = "card_unit_m36_destroyer", changed = "OnAfterDeckChanged", marker = "card_unit_routed_troops";
        if (KismetLibrary.Default?.Find(name)?.Locals is not IDictionary<string, IReadOnlyList<KismetStep>> locals
            || KismetLibrary.Default.Find(watcherName)?.Locals is not IDictionary<string, IReadOnlyList<KismetStep>> watcherLocals
            || locals.ContainsKey(filter) || locals.ContainsKey(selected) || watcherLocals.ContainsKey(changed)) return "无法安装多候选回复探针";
        KismetStep Store(int index, string variable, string field) => new(index, "set", null, Array.Empty<KismetExpr>(), Array.Empty<int>(),
            new KismetExpr { Var = variable }, null, -1, field, null) { DestinationScope = "instance" };
        locals[filter] = new[] {
            new KismetStep(0, "set", null, Array.Empty<KismetExpr>(), Array.Empty<int>(), new KismetExpr { Math = "Add_IntInt", Args = new[] {
                new KismetExpr { Var = "_auditScryCalls", Scope = "instance" }, new KismetExpr { Int = 1 }
            } }, null, -1, "_auditScryCalls", null) { DestinationScope = "instance" },
            new KismetStep(1, "set", null, Array.Empty<KismetExpr>(), Array.Empty<int>(),
                new KismetExpr { Var = "_auditScryValid", Context = new KismetExpr { Var = "card" } }, null, -1, "isValid", null) { DestinationScope = "local" },
            new KismetStep(2, "return", null, Array.Empty<KismetExpr>(), Array.Empty<int>(), null, null, -1, null, null),
        };
        locals[selected] = new[] { Store(0, "K2Node_Event_handTargetCardID", "_auditScryTarget"), Store(1, "K2Node_Event_instigatorID", "_auditScryInstigator"),
            new KismetStep(2, "set", null, Array.Empty<KismetExpr>(), Array.Empty<int>(), new KismetExpr { Var = "location", Context = new KismetExpr {
                Call = "GetCardFromID", Args = new[] { new KismetExpr { Var = "K2Node_Event_handTargetCardID" } }
            } }, null, -1, "_auditScryLocation", null) { DestinationScope = "instance" },
            new KismetStep(3, "return", null, Array.Empty<KismetExpr>(), Array.Empty<int>(), null, null, -1, null, null),
        };
        watcherLocals[changed] = new[] {
            new KismetStep(0, "call", "SpawnCardInHandBySide", new[] { new KismetExpr { Int = (int)Side.Right },
                new KismetExpr { Str = marker }, new KismetExpr { Int = 30 } }, Array.Empty<int>(), null, null, -1, null, null),
            new KismetStep(1, "return", null, Array.Empty<KismetExpr>(), Array.Empty<int>(), null, null, -1, null, null),
        };
        try
        {
            var patterns = new[] { new[] { 60, 61, 62 }, new[] { 61, 63, 65 }, new[] { 61, 64 }, new[] { 64, 65 } };
            foreach (Side side in new[] { Side.Left, Side.Right })
            foreach (bool full in new[] { false, true })
            foreach (bool unavailable in new[] { false, true })
            foreach (bool suppressed in new[] { false, true })
            foreach (var valid in patterns)
            foreach (int chosenId in valid)
            {
                var (engine, state) = EmptyBoard(db);
                var source = state.CreateWithId(name, side, 30, unavailable ? CardLocation.NotAvailable : CardLocation.Discard, 0);
                source.BlueprintVariables["_auditScryCalls"] = 0;
                if (suppressed) source.Keywords.Add(Keyword.Suppressed);
                if (full) for (int i = 0; i < 9; i++) state.CreateWithId(PlainUnit, side, 100 + i, side.HandOf(), i);
                for (int i = 0; i < 6; i++) state.CreateWithId(PlainUnit, side, 60 + i, side.DeckOf(), i * 4 + 2)
                    .BlueprintVariables["_auditScryValid"] = valid.Contains(60 + i);
                // Independent imperative oracle follows Insert, then Remove/Add.
                var expected = new List<int>(); int accepted = 0;
                foreach (int id in Enumerable.Range(60, 6)) { if (valid.Contains(id) && accepted < 3) expected.Insert(accepted++, id); else expected.Add(id); }
                var moved = expected.Take(3).Where(id => id != chosenId).ToArray();
                foreach (int id in moved) { expected.Remove(id); expected.Add(id); }
                var chosen = state.ById(chosenId)!;
                engine.Api.DrawChosenCardToHand(source, chosen);
                var actions = state.ActionLog.SelectMany(x => x.SubActions).ToArray();
                var receipt = actions.SingleOrDefault(x => x.Name == "ZActionNewDeck");
                var draw = actions.SingleOrDefault(x => x.Name == "ZActionDrawCardFromDeck");
                if (!state.Deck(side).Select(x => x.CardId).SequenceEqual(expected.Skip(1))
                    || receipt is null || !receipt.Values.Select(x => x.Name).SequenceEqual(new[] { "side", "cards", "spawnCards" })
                    || receipt.Values[0].Text != side.ToWire() || receipt.Values[1].Text != string.Join(";", expected) || receipt.Values[2].Text != ""
                    || draw is null || Array.IndexOf(actions, receipt) >= Array.IndexOf(actions, draw)
                    || draw.Values.First(x => x.Name == "instigatorID").Value != 0
                    || chosen.Location != (full ? CardLocation.Discard : side.HandOf())
                    || !Equals(source.BlueprintVariables.GetValueOrDefault("_auditScryTarget"), chosenId)
                    || !Equals(source.BlueprintVariables.GetValueOrDefault("_auditScryInstigator"), 30)
                    || Convert.ToInt32(source.BlueprintVariables.GetValueOrDefault("_auditScryLocation") ?? -1) != (int)chosen.Location
                    || Convert.ToInt32(source.BlueprintVariables["_auditScryCalls"]) != 6 || state.Random.ConsumedCount != 0)
                    return $"多候选移底/通知/回调错误：{side}/{full}/{unavailable}/{suppressed}/valid={string.Join(",", valid)}/chosen={chosenId}";
            }
            foreach (Side side in new[] { Side.Left, Side.Right })
            foreach (int mode in Enumerable.Range(0, 4))
            {
                var (engine, state) = EmptyBoard(db);
                var source = state.CreateWithId(name, side, 30, CardLocation.Discard, 0);
                source.BlueprintVariables["_auditScryCalls"] = 0;
                var watcher = state.CreateWithId(watcherName, side, 20, CardLocation.Discard, 0);
                watcher.Definition = new CardDefinition { Name = watcherName, Type = "infantry", UsedTriggers = new[] { changed } };
                for (int i = 0; i < 4; i++) state.CreateWithId(PlainUnit, side, 60 + i, side.DeckOf(), i).BlueprintVariables["_auditScryValid"] = true;
                CardInstance? replacement = null; int callbacks = 0; bool order = true;
                state.CardCreated += card => {
                    if (card.Name != marker) return;
                    callbacks++; card.Location = CardLocation.Discard;
                    var actions = state.ActionLog.SelectMany(x => x.SubActions).ToArray();
                    order &= actions.Count(x => x.Name == "ZActionNewDeck") == 1 && !actions.Any(x => x.Name == "ZActionDrawCardFromDeck");
                    if (mode is 1 or 2) state.Remove(source);
                    if (mode == 2) replacement = state.CreateWithId(name, side, 30, CardLocation.NotAvailable, 0);
                    if (mode == 3) source.Location = CardLocation.NotAvailable;
                };
                engine.Api.DrawChosenCardToHand(source, state.ById(61));
                if (!order || callbacks != 1 || !Equals(source.BlueprintVariables.GetValueOrDefault("_auditScryTarget"), 61)
                    || replacement is not null && replacement.BlueprintVariables.ContainsKey("_auditScryTarget"))
                    return $"新牌库/T3/抽牌顺序或原对象回调错误：{side}/mode={mode}/calls={callbacks}";
            }
            return null;
        }
        finally { locals.Remove(filter); locals.Remove(selected); watcherLocals.Remove(changed); }
    }

    private static string? SingletonScryDrawContract(CardDatabase db)
    {
        const string name = "card_unit_m36_destroyer", filter = "FilterCardsToScry", selected = "OnHandTargetSelected", changed = "OnAfterDeckChanged";
        if (KismetLibrary.Default?.Find(name)?.Locals is not IDictionary<string, IReadOnlyList<KismetStep>> locals
            || new[] { filter, selected, changed }.Any(locals.ContainsKey)) return "无法安装单候选抽牌探针";
        locals[filter] = new[] {
            new KismetStep(0, "set", null, Array.Empty<KismetExpr>(), Array.Empty<int>(),
                new KismetExpr { Math = "EqualEqual_IntInt", Args = new[] {
                    new KismetExpr { Var = "cardID", Context = new KismetExpr { Var = "card" } }, new KismetExpr { Int = 60 }
                } }, null, -1, "isValid", null) { DestinationScope = "local" },
            new KismetStep(1, "return", null, Array.Empty<KismetExpr>(), Array.Empty<int>(), null, null, -1, null, null),
        };
        locals[selected] = new[] {
            new KismetStep(0, "set", null, Array.Empty<KismetExpr>(), Array.Empty<int>(), new KismetExpr { Var = "K2Node_Event_handTargetCardID" },
                null, -1, "_auditSingletonTarget", null) { DestinationScope = "instance" },
            new KismetStep(1, "set", null, Array.Empty<KismetExpr>(), Array.Empty<int>(), new KismetExpr { Var = "K2Node_Event_instigatorID" },
                null, -1, "_auditSingletonInstigator", null) { DestinationScope = "instance" },
            new KismetStep(2, "set", null, Array.Empty<KismetExpr>(), Array.Empty<int>(),
                new KismetExpr { Var = "location", Context = new KismetExpr { Call = "GetCardFromID", Args = new[] { new KismetExpr { Int = 60 } } } },
                null, -1, "_auditSingletonLocation", null) { DestinationScope = "instance" },
            new KismetStep(3, "return", null, Array.Empty<KismetExpr>(), Array.Empty<int>(), null, null, -1, null, null),
        };
        // Same body as the T3 probe in DrawHandCapacityAfterDeckEvents:
        // compiled local programs persist in the test process's library cache.
        locals[changed] = new[] {
            new KismetStep(0, "call", "SpawnCardInHandBySide", new[] {
                new KismetExpr { Int = (int)Side.Right }, new KismetExpr { Str = "card_unit_routed_troops" }, new KismetExpr { Int = 30 }
            }, Array.Empty<int>(), null, null, -1, null, null),
            new KismetStep(1, "return", null, Array.Empty<KismetExpr>(), Array.Empty<int>(), null, null, -1, null, null),
        };
        try
        {
            foreach (Side side in new[] { Side.Left, Side.Right })
            foreach (bool full in new[] { false, true })
            foreach (bool suppressed in new[] { false, true })
            foreach (bool unavailable in new[] { false, true })
            foreach (bool autoplay in new[] { false, true })
            foreach (bool effect in new[] { false, true })
            {
                var (engine, state) = EmptyBoard(db);
                var selecting = state.CreateWithId(name, side, 30, unavailable ? CardLocation.NotAvailable : CardLocation.Discard, 0);
                selecting.ExtraPlayTriggers = 2;
                if (suppressed) selecting.Keywords.Add(Keyword.Suppressed);
                for (int i = 0; i < (full ? 9 : 8); i++) state.CreateWithId(PlainUnit, side, 100 + i, side.HandOf(), i * 3);
                var first = state.CreateWithId(PlainUnit, side, 61, side.DeckOf(), 2);
                var drawn = state.CreateWithId(PlainUnit, side, 60, side.DeckOf(), 17);
                var last = state.CreateWithId(PlainUnit, side, 62, side.DeckOf(), 29);
                if (autoplay) engine.Api.AddCustomGameplayTag(drawn, "autoplay");
                state.AddAutoPlayCards(0);
                var result = engine.Api.InvokeByName("selectCardToDraw", selecting, new object?[] { 30, true, effect, null },
                    new EffectContext { Engine = engine, State = state, Self = selecting, Controller = side.Opposite() }, out bool handled);
                var action = state.ActionLog.SelectMany(x => x.SubActions).SingleOrDefault(x => x.Name == "ZActionDrawCardFromDeck");
                if (!handled || !Equals(result, 60) || drawn.Location != (full ? CardLocation.Discard : side.HandOf())
                    || drawn.LocationNumber != (full ? 17 : 8) || first.LocationNumber != 2 || last.LocationNumber != 29
                    || !Equals(action?.Values.FirstOrDefault(x => x.Name == "instigatorID")?.Value, 30)
                    || !Equals(action?.Values.FirstOrDefault(x => x.Name == "cardID")?.Value, 60)
                    || !Equals(selecting.BlueprintVariables.GetValueOrDefault("_auditSingletonTarget"), 60)
                    || !Equals(selecting.BlueprintVariables.GetValueOrDefault("_auditSingletonInstigator"), 0)
                    || Convert.ToInt32(selecting.BlueprintVariables.GetValueOrDefault("_auditSingletonLocation") ?? -1) != (int)drawn.Location
                    || selecting.ExtraPlayTriggers != 2 || state.Random.ConsumedCount != 0
                    || !state.GetAutoPlayCards().SequenceEqual(!full && autoplay ? new[] { 0, 60 } : new[] { 0 }))
                    return $"单候选来源/编号/回调/队列错误：{side}/{full}/{suppressed}/{unavailable}/{autoplay}/{effect}";
            }
            foreach (Side side in new[] { Side.Left, Side.Right })
            foreach (int mode in Enumerable.Range(0, 4))
            {
                var (engine, state) = EmptyBoard(db);
                var original = state.CreateWithId(name, side, 30, CardLocation.Discard, 0);
                var watcher = state.CreateWithId(name, side, 20, CardLocation.Discard, 0);
                watcher.Definition = new CardDefinition { Name = name, Type = "infantry", UsedTriggers = new[] { changed } };
                var drawn = state.CreateWithId(PlainUnit, side, 60, side.DeckOf(), 17);
                CardInstance? replacement = null; int callbacks = 0;
                state.CardCreated += card => {
                    if (card.Name != "card_unit_routed_troops") return;
                    callbacks++; card.Location = CardLocation.Discard;
                    if (mode is 1 or 2) state.Remove(original);
                    if (mode == 2) replacement = state.CreateWithId(name, side.Opposite(), 30, CardLocation.NotAvailable, 0);
                    if (mode == 3) { original.Location = CardLocation.NotAvailable; original.Keywords.Add(Keyword.Suppressed); }
                };
                engine.Api.InvokeByName("selectCardToDraw", original, new object?[] { 30, true, false, null },
                    new EffectContext { Engine = engine, State = state, Self = original, Controller = side }, out _);
                if (callbacks != 1 || drawn.Location != side.HandOf()
                    || original.BlueprintVariables.ContainsKey("_auditSingletonTarget") != (mode is 0 or 3)
                    || replacement is not null && !Equals(replacement.BlueprintVariables.GetValueOrDefault("_auditSingletonTarget"), 60))
                    return $"抽后重新解析选择卡错误：{side}/mode={mode}/callbacks={callbacks}";
            }
            return null;
        }
        finally { locals.Remove(filter); locals.Remove(selected); locals.Remove(changed); }
    }

    private static string? SelectionHandCapacityGuard(CardDatabase db)
    {
        const string name = "card_unit_m36_destroyer", function = "GetChooseSpawnCards", field = "_auditSelectionPoolRead";
        if (KismetLibrary.Default?.Find(name)?.Locals is not IDictionary<string, IReadOnlyList<KismetStep>> locals
            || KismetLibrary.Default.FindLocalProgram(name, function) is not null) return "无法安装选择容量候选查询探针";
        locals[function] = new[] {
            new KismetStep(0, "set", null, Array.Empty<KismetExpr>(), Array.Empty<int>(), new KismetExpr { Bool = true },
                null, -1, field, null) { DestinationScope = "instance" },
            new KismetStep(1, "return", null, Array.Empty<KismetExpr>(), Array.Empty<int>(), null, null, -1, null, null),
        };
        try
        {
            foreach (Side side in new[] { Side.Left, Side.Right })
            foreach (int quantity in new[] { 8, 9, 10 })
            foreach (int excluded in new[] { 0, 1, 2 })
            foreach (bool oppositeOwner in new[] { false, true })
            foreach (bool fromTop in new[] { false, true })
            foreach (bool effect in new[] { false, true })
            foreach (bool unavailable in new[] { false, true })
            {
                var (engine, state) = EmptyBoard(db);
                var selecting = state.CreateWithId(name, side, 30, unavailable ? CardLocation.NotAvailable : CardLocation.Discard, 0);
                var decoy = state.CreateWithId(PlainUnit, side.Opposite(), 20, CardLocation.Discard, 0);
                for (int i = 0; i < quantity; i++)
                {
                    var hand = state.CreateWithId(i < excluded && i % 2 == 0 ? "card_event_resistance_new" : PlainUnit,
                        oppositeOwner ? side.Opposite() : side, 100 + i, side.HandOf(), 4 + i * 3);
                    if (i < excluded && i % 2 != 0) engine.Api.AddCustomGameplayTag(hand, "autoplay");
                }
                // The opposite physical hand is independently full. Receiver
                // and Controller point there, but the explicit selecting ID wins.
                for (int i = 0; i < 9; i++) state.CreateWithId(PlainUnit, side.Opposite(), 200 + i, side.Opposite().HandOf(), i);
                var drawn = state.CreateWithId(PlainUnit, side, 60, side.DeckOf(), 7);
                var ctx = new EffectContext { Engine = engine, State = state, Self = selecting, Controller = side.Opposite() };
                int replies = 0;
                engine.ChooseSpawnCard = (_, _) => { replies++; return null; };
                object? result = engine.Api.InvokeByName("selectCardToDraw", decoy,
                    new object?[] { 30, fromTop, effect, null }, ctx, out bool handled);
                bool full = quantity - excluded >= 9;
                bool blocked = !fromTop && !effect && full;
                bool poolRead = selecting.BlueprintVariables.ContainsKey(field);
                var draws = state.ActionLog.SelectMany(x => x.SubActions).Where(x => x.Name == "ZActionDrawCardFromDeck").ToArray();
                if (!handled || poolRead != (!fromTop && !blocked) || replies != 0 || state.Random.ConsumedCount != 0
                    || decoy.BlueprintVariables.ContainsKey(field)
                    || !Equals(result, fromTop ? 60 : 0)
                    || draws.Length != (fromTop ? 1 : 0)
                    || drawn.Location != (!fromTop ? side.DeckOf() : full ? CardLocation.Discard : side.HandOf()))
                    return $"选择守卫分支错误：{side}/{quantity}/{excluded}/{oppositeOwner}/top={fromTop}/effect={effect}/unavailable={unavailable}/pool={poolRead}";
            }
            return null;
        }
        finally { locals.Remove(function); }
    }

    private static string? DrawHandCapacityAutoplay(CardDatabase db)
    {
        foreach (Side deckSide in new[] { Side.Left, Side.Right })
        foreach (int route in Enumerable.Range(0, 3))
        foreach (int quantity in new[] { 0, 8, 9, 10 })
        foreach (int excluded in new[] { 0, 1, 2 })
        foreach (bool oppositeOwner in new[] { false, true })
        foreach (int drawnTag in Enumerable.Range(0, 4))
        {
            if (excluded > quantity) continue;
            var (engine, state) = EmptyBoard(db);
            Side recipient = route == 1 ? deckSide.Opposite() : deckSide;
            for (int i = 0; i < quantity; i++)
            {
                var hand = state.CreateWithId(i < excluded && i % 2 == 0 ? "card_event_resistance_new" : PlainUnit,
                    oppositeOwner ? recipient.Opposite() : recipient, 100 + i, recipient.HandOf(), 5 + i * 3);
                if (i < excluded && i % 2 != 0) engine.Api.AddCustomGameplayTag(hand, "autoplay");
            }
            string name = drawnTag is 1 or 2 ? "card_event_resistance_new" : PlainUnit;
            var first = state.CreateWithId(route == 2 ? PlainUnit : name, deckSide, 60, deckSide.DeckOf(), 7);
            var second = state.CreateWithId(route == 2 ? name : PlainUnit, deckSide, 61, deckSide.DeckOf(), 17);
            var drawn = route == 2 ? second : first;
            if (drawnTag == 2) drawn.RemovedGameplayTags.Add("autoplay");
            if (drawnTag == 3) engine.Api.AddCustomGameplayTag(drawn, "autoplay");
            object? result = route == 2 ? engine.Api.InvokeByName("DrawSpecificCardFromDeckBySide", drawn,
                new object?[] { 30, drawn.CardId, (int)deckSide, false },
                new EffectContext { Engine = engine, State = state, Controller = recipient.Opposite() }, out _)
                : engine.DrawCard(deckSide, instigatorId: 30, opponentDraw: route == 1);
            int expectedCount = quantity - excluded;
            bool full = expectedCount >= 9;
            var action = state.ActionLog.SelectMany(x => x.SubActions).SingleOrDefault(x => x.Name == "ZActionDrawCardFromDeck");
            if (drawn.Location != (full ? CardLocation.Discard : recipient.HandOf())
                || drawn.LocationNumber != (full ? route == 2 ? 17 : 7 : expectedCount)
                || drawn.Owner != (full ? deckSide : recipient) || drawn.OriginalOwner != deckSide
                || !Equals(action?.Values.FirstOrDefault(x => x.Name == "PreQtyInHand")?.Value, expectedCount)
                || !Equals(action?.Values.FirstOrDefault(x => x.Name == "handIsFull")?.Value, full ? 1 : 0)
                || !state.GetAutoPlayCards().SequenceEqual(!full && drawnTag is 1 or 3 ? new[] { drawn.CardId } : Array.Empty<int>())
                || route != 2 && (full ? result is not null : !ReferenceEquals(result, drawn))
                || state.Random.ConsumedCount != 0)
                return $"抽牌容量/编号/通知/入队错误：{deckSide}/{route}/{quantity}/{excluded}/{oppositeOwner}/{drawnTag}";
            for (int i = 0; i < quantity; i++)
                if (state.ById(100 + i)!.LocationNumber != 5 + i * 3) return "抽牌不得压紧已有手牌编号";
            if (!state.Deck(deckSide).Select(x => x.CardId).SequenceEqual(new[] { route == 2 ? 60 : 61 }))
                return "容量分支不得移除其他牌库成员";
        }
        return null;
    }

    private static string? DrawHandCapacityAfterDeckEvents(CardDatabase db)
    {
        const string name = "card_unit_m36_destroyer", trigger = "OnAfterDeckChanged", marker = "card_unit_routed_troops";
        if (KismetLibrary.Default?.Find(name)?.Locals is not IDictionary<string, IReadOnlyList<KismetStep>> locals
            || locals.ContainsKey(trigger)) return "无法安装抽牌容量T3探针";
        locals[trigger] = new[] {
            new KismetStep(0, "call", "SpawnCardInHandBySide", new[] {
                new KismetExpr { Int = (int)Side.Right }, new KismetExpr { Str = marker }, new KismetExpr { Int = 30 }
            }, Array.Empty<int>(), null, null, -1, null, null),
            new KismetStep(1, "return", null, Array.Empty<KismetExpr>(), Array.Empty<int>(), null, null, -1, null, null),
        };
        try
        {
            foreach (Side deckSide in new[] { Side.Left, Side.Right })
            foreach (int route in Enumerable.Range(0, 3))
            foreach (int quantity in new[] { 8, 9 })
            foreach (int mutation in Enumerable.Range(0, 5))
            {
                var (engine, state) = EmptyBoard(db);
                Side recipient = route == 1 ? deckSide.Opposite() : deckSide;
                var watcher = state.CreateWithId(name, deckSide, 20, CardLocation.Discard, 0);
                watcher.Definition = new CardDefinition { Name = name, Type = "infantry", UsedTriggers = new[] { trigger } };
                state.CreateWithId(PlainUnit, deckSide, 30, CardLocation.Discard, 0);
                for (int i = 0; i < quantity; i++) state.CreateWithId(PlainUnit, recipient, 100 + i, recipient.HandOf(), 5 + i * 3);
                var changed = state.ById(100)!;
                if (mutation == 2) engine.Api.AddCustomGameplayTag(changed, "autoplay");
                var incoming = state.CreateWithId(PlainUnit, recipient.Opposite(), 200, CardLocation.Discard, 33);
                var drawn = state.CreateWithId(PlainUnit, deckSide, 60, deckSide.DeckOf(), 17);
                int callbacks = 0; bool correct = true;
                state.CardCreated += card => {
                    if (card.Name != marker) return;
                    callbacks++;
                    // Keep the marker out of either capacity query. This is a
                    // controlled T3 callback, not a claimed real card combo.
                    card.Location = CardLocation.Discard;
                    correct &= drawn.Location == deckSide.DeckOf() && !state.Deck(deckSide).Any(x => x.CardId == drawn.CardId);
                    if (mutation == 1) engine.Api.AddCustomGameplayTag(changed, "autoplay");
                    if (mutation == 2) engine.Api.RemoveCustomGameplayTag(changed, "autoplay");
                    if (mutation == 3) changed.Location = recipient.Opposite().HandOf();
                    if (mutation == 4) incoming.Location = recipient.HandOf();
                };
                if (route == 2) engine.Api.InvokeByName("DrawSpecificCardFromDeckBySide", drawn,
                    new object?[] { 30, 60, (int)deckSide, false }, new EffectContext { Engine = engine, State = state, Controller = recipient }, out _);
                else engine.DrawCard(deckSide, instigatorId: 30, opponentDraw: route == 1);
                int expected = quantity + (mutation == 4 ? 1 : mutation is 1 or 3 ? -1 : 0);
                bool full = expected >= 9;
                var action = state.ActionLog.SelectMany(x => x.SubActions).SingleOrDefault(x => x.Name == "ZActionDrawCardFromDeck");
                if (!correct || callbacks != 1 || drawn.Location != (full ? CardLocation.Discard : recipient.HandOf())
                    || drawn.LocationNumber != (full ? 17 : expected)
                    || !Equals(action?.Values.FirstOrDefault(x => x.Name == "PreQtyInHand")?.Value, expected)
                    || !Equals(action?.Values.FirstOrDefault(x => x.Name == "handIsFull")?.Value, full ? 1 : 0))
                    return $"T3后容量查询错误：{deckSide}/{route}/{quantity}/{mutation}/calls={callbacks}";
            }
            return null;
        }
        finally { locals.Remove(trigger); }
    }

    private static string? DrawHandNumberAssignment(CardDatabase db)
    {
        foreach (Side deckSide in new[] { Side.Left, Side.Right })
        foreach (bool opponentDraw in new[] { false, true })
        foreach (bool specific in new[] { false, true })
        foreach (bool colliding in new[] { false, true })
        {
            var (engine, state) = EmptyBoard(db);
            Side recipient = opponentDraw ? deckSide.Opposite() : deckSide;
            var first = state.CreateWithId("card_unit_432_infantry_regiment", recipient, 100, recipient.HandOf(), 0);
            var second = state.CreateWithId(first.Name, recipient, 101, recipient.HandOf(), colliding ? 2 : 7);
            var drawn = state.CreateWithId(first.Name, deckSide, 60, deckSide.DeckOf(), 15);
            if (specific && opponentDraw) continue; // Native specific wrapper always draws to deckSide.
            if (specific) engine.Api.InvokeByName("DrawSpecificCardFromDeckBySide", drawn,
                new object?[] { 0, drawn.CardId, (int)deckSide, false },
                new EffectContext { Engine = engine, State = state, Controller = deckSide }, out _);
            else engine.DrawCard(deckSide, opponentDraw: opponentDraw);
            if (drawn.Location != recipient.HandOf() || drawn.LocationNumber != 2
                || first.LocationNumber != 0 || second.LocationNumber != (colliding ? 2 : 7))
                return $"抽牌入手编号错误：牌库方={deckSide} 对方抽牌={opponentDraw} 指定={specific} 编号碰撞={colliding}";
        }
        return null;
    }

    private static string? SpecificDrawFieldsAndOrder(CardDatabase db)
    {
        foreach (Side side in new[] { Side.Left, Side.Right })
        foreach (bool full in new[] { false, true })
        foreach (bool seen in new[] { false, true })
        foreach (int source in new[] { 0, 30 })
        {
            var (engine, state) = EmptyBoard(db);
            state.Turn = 1;
            var watcher = state.CreateWithId("card_event_betasom", side, 20, CardLocation.Discard, 0);
            watcher.EnteredPlayOnTurn = 1;
            if (full)
                for (int i = 0; i < GameState.HandCapacity; i++)
                    state.CreateWithId("card_unit_432_infantry_regiment", side, 100 + i, side.HandOf(), i);
            var first = state.CreateWithId("card_unit_432_infantry_regiment", side, 62, side.DeckOf(), 1);
            var target = state.CreateWithId(first.Name, side, 60, side.DeckOf(), 7);
            var last = state.CreateWithId(first.Name, side, 63, side.DeckOf(), 15);
            var context = new EffectContext { Engine = engine, State = state, Self = target, Controller = side.Opposite() };
            engine.Api.InvokeByName("DrawSpecificCardFromDeckBySide", target,
                new object?[] { source, target.CardId, (int)side, seen }, context, out _);
            var action = state.ActionLog.SelectMany(x => x.SubActions).LastOrDefault(x => x.Name == "ZActionDrawCardFromDeck");
            if (target.Location != (full ? CardLocation.Discard : side.HandOf()) || target.CardSeen != seen
                || first.LocationNumber != 1 || last.LocationNumber != 15 || (full && target.LocationNumber != 7)
                || !state.Deck(side).Select(x => x.CardId).SequenceEqual(new[] { 62, 63 })
                || !engine.Api.HasCustomGameplayTag(first, "subtype.navy")
                || action?.Values.FirstOrDefault(x => x.Name == "cardID")?.Value != 60
                || action.Values.FirstOrDefault(x => x.Name == "instigatorID")?.Value != source)
                return $"指定抽牌参数或编号错误：方={side} 满手={full} 公开={seen} 来源={source}";
        }
        return null;
    }

    private static string? OpponentDrawRouting(CardDatabase db)
    {
        const string name = "card_unit_coastwatchers";
        const string trigger = "OnCardDrawnFromDeck";
        if (KismetLibrary.Default?.Find(name)?.Locals is not IDictionary<string, IReadOnlyList<KismetStep>> locals
            || KismetLibrary.Default.FindProgram(name, trigger) is not null) return "无法安全添加对方抽牌参数探针";
        locals.Add(trigger, new[] {
            new KismetStep(0, "set", null, Array.Empty<KismetExpr>(), Array.Empty<int>(),
                new KismetExpr { Var = "K2Node_Event_drawnSide", Scope = "local" }, null, -1, "_auditRecipientSide", null) { DestinationScope = "instance" },
            new KismetStep(1, "return", null, Array.Empty<KismetExpr>(), Array.Empty<int>(), null, null, -1, null, null) });
        try
        {
            foreach (Side deckSide in new[] { Side.Left, Side.Right })
            foreach (bool recipientFull in new[] { false, true })
            foreach (bool seen in new[] { false, true })
            {
                var (engine, state) = EmptyBoard(db);
                state.Turn = 1;
                Side recipient = deckSide.Opposite();
                var watcher = state.CreateWithId("card_event_betasom", deckSide, 20, CardLocation.Discard, 0);
                watcher.EnteredPlayOnTurn = 1;
                Side filled = recipientFull ? recipient : deckSide;
                for (int i = 0; i < GameState.HandCapacity; i++)
                    state.CreateWithId("card_unit_432_infantry_regiment", filled, 100 + i, filled.HandOf(), i);
                var card = state.CreateWithId(name, deckSide, 60, deckSide.DeckOf(), 0);
                var next = state.CreateWithId("card_unit_432_infantry_regiment", deckSide, 61, deckSide.DeckOf(), 1);
                var context = new EffectContext { Engine = engine, State = state, Self = card, Controller = deckSide };
                engine.Api.InvokeByName("DrawCardsFromDeckBySide", card,
                    new object?[] { 30, (int)deckSide, 1, seen, true, null, 0.4 }, context, out _);
                var action = state.ActionLog.SelectMany(x => x.SubActions).LastOrDefault(x => x.Name == "ZActionDrawCardFromDeck");
                bool ownCalled = card.BlueprintVariables.ContainsKey("_auditRecipientSide");
                if (card.Location != (recipientFull ? CardLocation.Discard : recipient.HandOf())
                    || card.Owner != (recipientFull ? deckSide : recipient) || card.OriginalOwner != deckSide || card.CardSeen != seen
                    || state.Deck(deckSide).Count != 1 || state.Deck(deckSide)[0] != next
                    || !engine.Api.HasCustomGameplayTag(next, "subtype.navy")
                    || ownCalled == recipientFull || (!recipientFull && Convert.ToInt32(card.BlueprintVariables["_auditRecipientSide"]) != (int)recipient)
                    || action?.Values.FirstOrDefault(x => x.Name == "side")?.Text != recipient.ToWire()
                    || action.Values.FirstOrDefault(x => x.Name == "oppSide")?.Value != 1)
                    return $"对方抽牌路由错误：牌库方={deckSide} 收牌方满手={recipientFull} 公开={seen}";
            }
            return null;
        }
        finally { locals.Remove(trigger); }
    }

    private static string? OpponentDrawFatigue(CardDatabase db)
    {
        foreach (Side deckSide in new[] { Side.Left, Side.Right })
        {
            var (engine, state) = EmptyBoard(db);
            int ownHp = state.HqDefense(deckSide), otherHp = state.HqDefense(deckSide.Opposite());
            var context = new EffectContext { Engine = engine, State = state, Controller = deckSide.Opposite() };
            engine.Api.InvokeByName("DrawCardsFromDeckBySide", null,
                new object?[] { 0, (int)deckSide, 1, false, true, null, 0.4 }, context, out _);
            if (state.Fatigue(deckSide) != 1 || state.Fatigue(deckSide.Opposite()) != 0
                || state.HqDefense(deckSide) != ownHp - 1 || state.HqDefense(deckSide.Opposite()) != otherHp)
                return "对方抽牌空牌库疲劳不应转移给收牌方";
        }
        return null;
    }

    private static string? DrawSeenContract(CardDatabase db)
    {
        const string name = "card_unit_m36_destroyer";
        const string trigger = "OnCardDrawnFromDeck";
        if (KismetLibrary.Default?.Find(name)?.Locals is not IDictionary<string, IReadOnlyList<KismetStep>> locals
            || KismetLibrary.Default.FindProgram(name, trigger) is not null) return "无法安全添加抽牌公开探针";
        locals.Add(trigger, new[] {
            new KismetStep(0, "set", null, Array.Empty<KismetExpr>(), Array.Empty<int>(),
                new KismetExpr { Var = "cardSeen", Scope = "instance" }, null, -1, "_auditSeenAtOwn", null) { DestinationScope = "instance" },
            new KismetStep(1, "return", null, Array.Empty<KismetExpr>(), Array.Empty<int>(), null, null, -1, null, null) });
        try
        {
            foreach (Side side in new[] { Side.Left, Side.Right })
            foreach (bool full in new[] { false, true })
            foreach (bool initiallySeen in new[] { false, true })
            foreach (bool markSeen in new[] { false, true })
            {
                var (engine, state) = EmptyBoard(db);
                if (full)
                    for (int i = 0; i < GameState.HandCapacity; i++)
                        state.CreateWithId("card_unit_432_infantry_regiment", side, 100 + i, side.HandOf(), i);
                var card = state.CreateWithId(name, side, 60, side.DeckOf(), 0);
                card.CardSeen = initiallySeen;
                var context = new EffectContext { Engine = engine, State = state, Self = card, Controller = side };
                engine.Api.InvokeByName("DrawCardsFromDeckBySide", card,
                    new object?[] { 0, (int)side, 1, markSeen, false, null, 0.4 }, context, out _);
                bool expected = initiallySeen || markSeen;
                bool ownCalled = card.BlueprintVariables.ContainsKey("_auditSeenAtOwn");
                if (card.CardSeen != expected || ownCalled == full
                    || (!full && Convert.ToBoolean(card.BlueprintVariables["_auditSeenAtOwn"]) != initiallySeen))
                    return $"抽牌公开时机错误：方={side} 满手={full} 原公开={initiallySeen} 请求公开={markSeen}";
            }
            return null;
        }
        finally { locals.Remove(trigger); }
    }

    private static string? DrawNotificationInstigator(CardDatabase db)
    {
        foreach (Side side in new[] { Side.Left, Side.Right })
        foreach (bool full in new[] { false, true })
        foreach (int sourceId in new[] { 0, 30 })
        {
            var (engine, state) = EmptyBoard(db);
            var caller = state.CreateWithId("card_unit_432_infantry_regiment", Side.Left, 20, CardLocation.Discard, 0);
            if (full)
                for (int i = 0; i < GameState.HandCapacity; i++)
                    state.CreateWithId(caller.Name, side, 100 + i, side.HandOf(), i);
            state.CreateWithId(caller.Name, side, 60, side.DeckOf(), 0);
            var context = new EffectContext { Engine = engine, State = state, Self = caller, Controller = Side.Left };
            engine.Api.InvokeByName("DrawCardsFromDeckBySide", caller,
                new object?[] { sourceId, (int)side, 1, false, false, null, 0.4 }, context, out _);
            var action = state.ActionLog.SelectMany(x => x.SubActions).LastOrDefault(x => x.Name == "ZActionDrawCardFromDeck");
            if (action?.Values.FirstOrDefault(x => x.Name == "instigatorID") is not { } source || source.Value != sourceId
                || action.Values.FirstOrDefault(x => x.Name == "cardType") is not { } type || type.Value != -1 || type.Text != caller.Name)
                return $"抽牌通知未保留显式来源{sourceId}或卡名：方={side}，满手={full}";
        }
        return null;
    }

    private static string? DrawNotificationNoFatigue(CardDatabase db)
    {
        foreach (Side side in new[] { Side.Left, Side.Right })
        foreach (bool full in new[] { false, true })
        {
            var (engine, state) = EmptyBoard(db);
            engine.DrawCard(side); // establish nonzero fatigue before the real draw
            if (full)
                for (int i = 0; i < GameState.HandCapacity; i++)
                    state.CreateWithId("card_unit_432_infantry_regiment", side, 100 + i, side.HandOf(), i);
            state.CreateWithId("card_unit_432_infantry_regiment", side, 60, side.DeckOf(), 0);
            int actions = state.ActionLog.Count;
            engine.DrawCard(side);
            var draw = state.ActionLog.Skip(actions).SelectMany(x => x.SubActions).LastOrDefault(x => x.Name == "ZActionDrawCardFromDeck");
            if (state.Fatigue(side) <= 0 || draw is null || draw.Values.Any(x => x.Name == "nextFatigueDamage"))
                return $"非空抽牌不应编码疲劳预告：方={side}，满手={full}";
        }
        return null;
    }

    private static string? OwnDrawEventBoundary(CardDatabase db)
    {
        const string name = "card_unit_typhoon_mk_ib";
        const string trigger = "OnCardDrawnFromDeck";
        if (KismetLibrary.Default?.Find(name)?.Locals is not IDictionary<string, IReadOnlyList<KismetStep>> locals
            || KismetLibrary.Default.FindProgram(name, trigger) is not null) return "无法安全添加自身抽牌探针";
        // Synthetic own callback records both parameters and suppresses a
        // registered observer before the following T42 query takes place.
        locals.Add(trigger, new[] {
            new KismetStep(0, "set", null, Array.Empty<KismetExpr>(), Array.Empty<int>(),
                new KismetExpr { Var = "K2Node_Event_StartOfTurnDraw", Scope = "local" }, null, -1, "_auditOwnStart", null) { DestinationScope = "instance" },
            new KismetStep(1, "set", null, Array.Empty<KismetExpr>(), Array.Empty<int>(),
                new KismetExpr { Var = "K2Node_Event_drawnSide", Scope = "local" }, null, -1, "_auditOwnSide", null) { DestinationScope = "instance" },
            new KismetStep(2, "call", "SuppressUnit", new[] { new KismetExpr { Int = 21 } }, Array.Empty<int>(), null, null, -1, null, null),
            new KismetStep(3, "return", null, Array.Empty<KismetExpr>(), Array.Empty<int>(), null, null, -1, null, null) });
        try
        {
            foreach (Side side in new[] { Side.Left, Side.Right })
            foreach (int zone in new[] { 0, 1, 2 })
            foreach (bool suppressed in new[] { false, true })
            foreach (bool start in new[] { false, true })
            {
                var (engine, state) = EmptyBoard(db);
                var observer = state.CreateWithId("card_unit_67th_baranovichi", side, 21, side.HqOf(), 1);
                var card = state.CreateWithId(name, side, 60,
                    zone == 0 ? side.HandOf() : zone == 1 ? CardLocation.Discard : CardLocation.NotAvailable, 0);
                if (suppressed) card.Keywords.Add(Keyword.Suppressed);
                var trace = new List<string>();
                engine.Api.TriggerTrace = trace;
                engine.FireEnteredHandFromDeckEvents(card, side, start);
                if (!card.BlueprintVariables.ContainsKey("_auditOwnStart")
                    || Convert.ToBoolean(card.BlueprintVariables.GetValueOrDefault("_auditOwnStart")) != start
                    || Convert.ToInt32(card.BlueprintVariables.GetValueOrDefault("_auditOwnSide")) != (int)side
                    || !observer.IsSuppressed
                    || trace.Any(x => x.StartsWith("OnOtherCardDrawnFromDeck → card_unit_67th_baranovichi#21", StringComparison.Ordinal)))
                    return $"自身抽牌派发或查询顺序错误：方={side} 区={zone} 抑制={suppressed} 回合开始={start}";
            }
            return null;
        }
        finally { locals.Remove(trigger); }
    }

    private static string? DrawObserverSnapshot(CardDatabase db)
    {
        const string probe = "card_unit_41st_infantry_regiment";
        const string trigger = "OnOtherCardDrawnFromDeck";
        if (KismetLibrary.Default?.Find(probe)?.Locals is not IDictionary<string, IReadOnlyList<KismetStep>> locals
            || KismetLibrary.Default.FindProgram(probe, trigger) is not null) return "无法安全添加T42临时接收函数";
        locals.Add(trigger, new[] {
            new KismetStep(0, "call", "SuppressUnit", new[] { new KismetExpr { Int = 21 } }, Array.Empty<int>(), null, null, -1, null, null),
            new KismetStep(1, "return", null, Array.Empty<KismetExpr>(), Array.Empty<int>(), null, null, -1, null, null) });
        try
        {
            foreach (bool initiallySuppressed in new[] { false, true })
            {
                var (engine, state) = EmptyBoard(db);
                state.CreateWithId(probe, Side.Left, 20, CardLocation.BoardHqLeft, 1);
                var later = state.CreateWithId("card_unit_67th_baranovichi", Side.Left, 21, CardLocation.BoardHqLeft, 2);
                if (initiallySuppressed) later.Keywords.Add(Keyword.Suppressed);
                var drawn = state.CreateWithId("card_unit_light_infantry", Side.Left, 60, CardLocation.DeckLeft, 0);
                var trace = new List<string>();
                engine.Api.TriggerTrace = trace;
                engine.DrawCard(Side.Left);
                bool received = trace.Any(x => x.StartsWith(trigger + " → card_unit_67th_baranovichi#21", StringComparison.Ordinal));
                // Earlier location/creation phases can already grant Alpine;
                // this probe asserts dispatch eligibility, not its provenance.
                if (!later.IsSuppressed || received != !initiallySuppressed)
                    return $"T42快照错误：查询前抑制={initiallySuppressed}，接收={received}";
            }
            return null;
        }
        finally { locals.Remove(trigger); }
    }

    private static string? DrawObserverLocationAndSelf(CardDatabase db)
    {
        var (engine, state) = EmptyBoard(db);
        state.CreateWithId("card_unit_67th_baranovichi", Side.Left, 20, CardLocation.NotAvailable, 0);
        var drawn = state.CreateWithId("card_event_cross_of_lorraine", Side.Left, 60, CardLocation.DeckLeft, 0);
